accounts/public/account.css.full:
/* Comquat account pages. Tokens from the Comquat Brand design system:
   leaf #1F6B45, leaf-light #3E9A5F, kumquat #FF8A1F, kumquat-text #B44E00,
   ink #17191C, peel #FFF3E2, pith #E9DCC8, muted #5B5F66. */
:root{--leaf:#1F6B45;--leaf2:#3E9A5F;--kq:#FF8A1F;--kqt:#B44E00;--ink:#17191C;--peel:#FFF3E2;--pith:#E9DCC8;--muted:#5B5F66;--err:#A8321E}
*{box-sizing:border-box}
html,body{margin:0;background:var(--peel);color:var(--ink);font-family:'DM Sans',system-ui,-apple-system,sans-serif;font-size:16px;line-height:1.55}
a{color:var(--leaf)}
.cq-head{display:grid;grid-template-columns:minmax(0,1fr);row-gap:14px;padding:18px max(24px,calc((100% - 1032px) / 2)) 14px;border-bottom:1px solid var(--pith);background:#fff;position:relative}
.cq-head .cq-book{position:absolute;top:18px;right:max(24px,calc((100% - 1032px) / 2));background:#FF8A1F;color:#17191C;font-weight:700;font-size:13px;letter-spacing:.04em;text-transform:uppercase;text-decoration:none;padding:8px 16px;border-radius:999px;line-height:1.2;white-space:nowrap}
.cq-head .cq-book:hover{background:#E2650B}
@media (max-width:480px){.cq-head .cq-book{font-size:11.5px;padding:7px 11px;top:20px;right:16px}}
.cq-head .cq-brand{justify-self:start}
.cq-brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;line-height:1}
.cq-brand img{height:32px;width:auto;display:block}
.cq-feat{font-weight:700;font-size:12px;letter-spacing:.12em;text-transform:uppercase;padding:6px 12px;border-radius:999px;background:var(--ink);color:var(--peel)}
.cq-head nav{display:flex;align-items:center;flex-wrap:wrap;gap:8px 16px;font-size:13.5px;font-weight:500;letter-spacing:.04em;text-transform:uppercase}
.cq-head nav a{color:var(--muted);text-decoration:none;white-space:nowrap}
.cq-head nav a.active{color:var(--leaf)}
.cq-head nav .linkbtn{font:inherit;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}
@media (max-width:760px){.cq-head nav{flex-wrap:nowrap;overflow-x:auto;gap:18px;padding-bottom:4px;-webkit-overflow-scrolling:touch;scrollbar-width:none}.cq-head nav::-webkit-scrollbar{display:none}}
@media (max-width:480px){.cq-head .cq-feat{display:none}}
.cq-head nav a:hover{color:var(--leaf)}
main{max-width:620px;margin:40px auto 64px;padding:0 20px}
main.wide{max-width:760px}
h1{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-weight:800;font-size:clamp(30px,5vw,42px);letter-spacing:-.02em;line-height:1.08;margin:0 0 10px}
h2{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-weight:800;font-size:22px;letter-spacing:-.01em;margin:0 0 6px}
.lede{color:var(--muted);margin:0 0 26px;font-size:17px}
.card{background:#fff;border:1px solid var(--pith);border-radius:16px;padding:26px;margin:0 0 20px}
.tabs{display:flex;gap:6px;background:#fff;border:1px solid var(--pith);border-radius:999px;padding:5px;margin:0 0 20px;width:max-content}
.tabs button{border:0;background:none;font:inherit;font-weight:700;font-size:14.5px;padding:8px 18px;border-radius:999px;cursor:pointer;color:var(--muted)}
.tabs button[aria-selected="true"]{background:var(--leaf);color:var(--peel)}
label{display:block;font-weight:700;font-size:14px;margin:0 0 16px}
label .hint{display:block;font-weight:400;color:var(--muted);font-size:13.5px;margin-top:2px}
input[type=text],input[type=email],input[type=password]{display:block;width:100%;margin-top:6px;padding:12px 14px;font:inherit;font-weight:400;border:1.5px solid var(--pith);border-radius:10px;background:#fff;color:var(--ink)}
input:focus,button:focus-visible,a:focus-visible{outline:3px solid var(--leaf2);outline-offset:2px}
.check{display:flex;gap:12px;align-items:flex-start;font-weight:400;font-size:15px;margin:0 0 12px;cursor:pointer}
.check input{width:20px;height:20px;margin:2px 0 0;accent-color:var(--leaf);flex:0 0 auto}
.check strong{font-weight:700}
fieldset{border:0;margin:6px 0 18px;padding:0}
legend{font-weight:700;font-size:14px;margin:0 0 10px;padding:0}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:6px;padding:12px 22px;font:inherit;font-weight:700;font-size:16px;cursor:pointer;text-decoration:none;box-shadow:0 2px 0 rgba(23,25,28,.18)}
.btn-primary{background:var(--leaf);color:var(--peel)}
.btn-primary:hover{background:#17573a}
.btn-ghost{background:#fff;color:var(--ink);border:1.5px solid var(--pith);box-shadow:none}
.btn-ghost:hover{border-color:var(--leaf);color:var(--leaf)}
.btn-danger{background:#fff;color:var(--err);border:1.5px solid var(--err);box-shadow:none}
.btn[disabled]{opacity:.55;cursor:wait}
.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.linkbtn{background:none;border:0;padding:0;font:inherit;color:var(--leaf);text-decoration:underline;cursor:pointer}
.msg{border-radius:10px;padding:12px 14px;margin:0 0 18px;font-size:15px}
.msg.ok{background:#E6F2EA;color:#174F33}
.msg.err{background:#FBE9E4;color:var(--err)}
.msg:empty{display:none}
.small{font-size:14px;color:var(--muted)}
.note{border-left:4px solid var(--kq);background:#fff;padding:14px 16px;border-radius:0 10px 10px 0;font-size:15px;margin:0 0 20px}
.kv{display:grid;grid-template-columns:120px 1fr;gap:6px 14px;margin:0 0 6px;font-size:15px}
.kv dt{color:var(--muted)}.kv dd{margin:0;font-weight:500;word-break:break-all}
.soon li{margin:0 0 6px}
.tool-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 0}
.tool{display:flex;flex-direction:column;gap:6px;background:var(--peel);border:1px solid var(--pith);border-radius:14px;padding:16px;color:var(--ink);text-decoration:none}
a.tool:hover{border-color:var(--leaf);box-shadow:0 4px 14px rgba(31,107,69,.12)}
.tool strong{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-size:18px;color:var(--leaf)}
.tool span{font-size:14.5px;color:var(--muted);flex:1}
.tool em{font-style:normal;font-weight:700;font-size:14.5px;align-self:flex-start;background:var(--leaf);color:#fff;border-radius:999px;padding:8px 14px;margin-top:4px}
.tool-soon{opacity:.85}
.soon-tag{display:inline-block;margin-left:4px;font-family:'DM Sans',sans-serif;font-size:10.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--kqt);border:1px solid var(--kq);border-radius:999px;padding:1px 7px;vertical-align:3px;background:#fff}
@media (max-width:720px){.tool-grid{grid-template-columns:1fr}}
.docs{list-style:none;margin:14px 0 0;padding:0}
.docs li{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:14px 0;border-top:1px solid var(--pith)}
.docs li:first-child{border-top:0;padding-top:4px}
.docs .doc-kind{display:inline-block;font-size:11.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--leaf);margin:0 0 2px}
.docs .doc-title{display:block;font-weight:700;font-size:15.5px}
.docs .doc-meta{display:block;font-size:13.5px;color:var(--muted)}
.docs .doc-actions{display:flex;gap:10px;align-items:center}
.docs .btn{padding:8px 14px;font-size:14px}
.hidden{display:none!important}
footer{text-align:center;font-size:13.5px;color:var(--muted);padding:0 20px 40px}
@media (max-width:560px){.card{padding:20px}.tabs{width:100%}.tabs button{flex:1;padding:8px 10px}}
.sep{border:0;border-top:1px solid var(--pith);margin:24px 0}

accounts/public/fresh.css.full:
/* Comquat "fresh" look: the bright style first made for the CV builder, shared by
   CV Rewrite, Interview Prep and the account pages. Served at /account/fresh.css
   by both apps. Load it LAST: every rule is scoped to body.fx so it wins over the
   older page themes. */
body.fx{--kq:#FF8A1F;--coral:#F25C54;--pink:#E8467C;--sun:#FFB547;--leaf:#1F6B45;--ink:#17191C;--peel:#FFF3E2;--pith:#E9DCC8;--cream:#FFF8EE;--muted:#5B5F66;--violet:#7C3AED;
  background:var(--cream)!important;color:var(--ink)!important;font-family:'DM Sans',system-ui,-apple-system,sans-serif!important}
body.fx h1,body.fx h2,body.fx h3{font-family:'Bricolage Grotesque','DM Sans',sans-serif!important;color:var(--ink)!important;letter-spacing:-.01em}
body.fx main a{color:#B44E00}

/* ---- the banner ---- */
body.fx{--hero:linear-gradient(120deg,#FF8A1F 0%,#F25C54 55%,#E8467C 100%);--badge:linear-gradient(135deg,#FF8A1F,#F25C54);--app:#FF8A1F}
body.fx .fx-hero{padding:0!important;margin:0!important;background:var(--hero)!important;color:#fff!important;position:relative;overflow:hidden;border:0!important}
body.fx .fx-hero:before,body.fx .fx-hero:after{content:"";position:absolute;border-radius:50%;pointer-events:none}
body.fx .fx-hero:before{width:340px;height:340px;right:-90px;top:-150px;background:#fff;opacity:.18}
body.fx .fx-hero:after{width:180px;height:180px;left:46%;bottom:-120px;background:var(--sun);opacity:.35}
body.fx .fx-hero-in{max-width:1080px;box-sizing:border-box;margin:0 auto;padding:34px 24px 30px;position:relative;z-index:1}
body.fx .fx-kicker{display:inline-block;font-weight:700;font-size:12.5px;letter-spacing:.12em;text-transform:uppercase;background:rgba(255,255,255,.2);border-radius:999px;padding:5px 12px;margin:0 0 10px;color:#fff}
body.fx .fx-hero h1{color:#fff!important;font-size:clamp(34px,6vw,54px)!important;font-weight:800!important;line-height:1.05!important;margin:0 0 10px!important}
body.fx .fx-hero p{color:#FFF4EA!important}
body.fx .fx-lede{font-size:17.5px;max-width:640px;margin:0 0 16px}
body.fx .fx-how{list-style:none;display:flex;flex-wrap:wrap;gap:10px;margin:0;padding:0}
body.fx .fx-how li{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);border-radius:999px;padding:6px 14px 6px 6px;font-weight:700;font-size:14.5px;color:#fff}
body.fx .fx-how .d{width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;color:var(--ink);background:var(--sun)}
body.fx .fx-how li:nth-child(2) .d{background:#fff}
body.fx .fx-how li:nth-child(3) .d{background:#A7F3D0}
body.fx .fx-how li:nth-child(4) .d{background:#C4B5FD}
body.fx .fx-hero-sm .fx-hero-in{padding:26px 24px 24px}
body.fx .fx-hero-sm h1{font-size:clamp(30px,5vw,44px)!important}
@media (max-width:700px){body.fx .fx-how{display:none}body.fx .fx-hero h1{font-size:34px!important}body.fx .fx-lede{font-size:15.5px;margin:0}body.fx .fx-hero-in{padding:24px 18px 22px}}

/* ---- step chips ---- */
body.fx .fx-steps,body.fx .steps{display:flex!important;gap:8px!important;overflow-x:auto;padding:16px 2px 12px!important;margin:0 0 6px!important;scrollbar-width:thin;border:0!important;background:transparent!important}
body.fx .steps .s,body.fx .fx-steps .fx-s{flex:0 0 auto;display:flex;align-items:center;gap:8px;border:2px solid var(--pith)!important;background:#fff!important;border-radius:999px!important;padding:7px 16px!important;font-weight:700!important;font-size:14px!important;color:var(--ink)!important;letter-spacing:0!important;text-transform:none!important;font-family:'DM Sans',sans-serif!important;cursor:default}
body.fx .steps .s.done,body.fx .fx-steps .fx-s.done{border-color:var(--leaf)!important;color:var(--leaf)!important;cursor:pointer}
body.fx .steps .s.done:before,body.fx .fx-steps .fx-s.done:before{content:"✓";display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:var(--leaf);color:#fff;font-size:12px}
body.fx .steps .s.active,body.fx .fx-steps .fx-s.active{background:var(--ink)!important;color:#fff!important;border-color:var(--ink)!important}
body.fx .steps .s.active:before,body.fx .fx-steps .fx-s.active:before{content:"";width:10px;height:10px;border-radius:50%;background:var(--app)}

/* ---- cards ---- */
body.fx .panel,body.fx .fx-card,body.fx main .card{background:#fff!important;border:1px solid var(--pith)!important;border-radius:20px!important;padding:24px 26px!important;box-shadow:0 10px 30px rgba(23,25,28,.06)!important;color:var(--ink)!important}
@media (max-width:640px){body.fx .panel,body.fx .fx-card,body.fx main .card{padding:18px 16px!important;border-radius:16px!important}}
body.fx .panel h2,body.fx main .card>h2{display:flex;align-items:center;gap:12px;font-size:26px!important;font-weight:800!important;margin:0 0 10px!important}
body.fx .fx-num{width:38px;height:38px;border-radius:12px;background:var(--badge);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:19px;flex:0 0 38px;transform:rotate(-4deg);font-family:'Bricolage Grotesque',sans-serif}

/* ---- tips and notices ---- */
body.fx .notice,body.fx .fx-tip{background:var(--peel)!important;border:0!important;border-left:4px solid var(--kq)!important;border-radius:0 12px 12px 0!important;padding:11px 14px!important;color:#3F444B!important}
body.fx .notice.hidden{display:none!important}

/* ---- form fields ---- */
body.fx input[type=text],body.fx input[type=email],body.fx input[type=url],body.fx input[type=tel],body.fx input[type=password],body.fx textarea,body.fx select{width:100%;box-sizing:border-box;font:inherit!important;font-size:16px!important;padding:11px 13px!important;border:2px solid var(--pith)!important;border-radius:12px!important;background:#fff!important;color:var(--ink)!important;transition:border-color .15s,box-shadow .15s}
body.fx input:focus,body.fx textarea:focus,body.fx select:focus{outline:none!important;border-color:var(--kq)!important;box-shadow:0 0 0 4px rgba(255,138,31,.18)!important}
body.fx input[type=file]{font:inherit;font-size:14px;padding:10px;border:2px dashed #F4C9A0;border-radius:12px;background:#FFF6EC;width:100%;box-sizing:border-box;color:var(--muted)}
body.fx input[type=file]::file-selector-button{border:0;border-radius:999px;background:var(--ink);color:#fff;font:inherit;font-weight:700;padding:7px 14px;margin-right:10px;cursor:pointer}
body.fx details>summary{cursor:pointer;font-weight:700!important;color:var(--leaf)!important;font-family:'DM Sans',sans-serif!important;text-transform:none!important;letter-spacing:0!important;font-size:15px!important}

/* ---- buttons ---- */
body.fx .btn,body.fx .btn-primary,body.fx .btn-secondary{border-radius:999px!important;font-weight:700!important;font-family:'DM Sans',sans-serif!important;letter-spacing:0!important;text-transform:none!important}
body.fx .btn.accent,body.fx main .btn-primary,body.fx .panel .btn-primary,body.fx .btn:not(.ghost):not(.btn-ghost):not(.btn-danger){background:var(--leaf)!important;color:#fff!important;border:0!important;box-shadow:0 6px 16px rgba(31,107,69,.22)!important;padding:12px 22px!important}
body.fx .btn.accent:hover,body.fx main .btn-primary:hover{background:#17573a!important}
body.fx .btn.ghost,body.fx .btn-ghost,body.fx .btn-secondary{background:#fff!important;color:var(--ink)!important;border:2px solid var(--pith)!important;box-shadow:none!important}
body.fx .btn.ghost:hover,body.fx .btn-ghost:hover,body.fx .btn-secondary:hover{border-color:var(--leaf)!important;color:var(--leaf)!important}
body.fx .fx-spark{background:linear-gradient(120deg,var(--violet),var(--pink))!important;color:#fff!important;box-shadow:0 6px 16px rgba(124,58,237,.28)!important;border:0!important}
/* record buttons */
body.fx .record-btn,body.fx [data-rec]{display:inline-flex!important;align-items:center;gap:6px;border:2px solid var(--coral)!important;background:#fff!important;color:#C2362E!important;border-radius:999px!important;padding:7px 14px!important;font:inherit!important;font-weight:700!important;font-size:14px!important;cursor:pointer;box-shadow:none!important}
body.fx .record-btn:hover,body.fx [data-rec]:hover{background:#FFF0EF!important}
body.fx .record-btn.recording,body.fx .record-btn.is-recording{background:var(--coral)!important;color:#fff!important}

/* ---- footer ---- */
body.fx footer,body.fx .site-footer{background:transparent}

/* ---- shared layout bits ---- */
body.fx .fx-wrap{max-width:1080px;box-sizing:border-box;margin:0 auto;padding:0 24px}
body.fx .fx-hero .lede{color:#FFF4EA!important;font-size:17.5px;max-width:640px;margin:0}

/* ---- My account and sign-in ---- */
body.fx-account main{margin-top:26px}
body.fx-account .tools .tool-grid{gap:12px}
body.fx-account .tool{border:0!important;border-radius:18px!important;padding:16px!important;color:#fff!important;box-shadow:0 8px 22px rgba(23,25,28,.12);transition:transform .15s}
body.fx-account .tool:hover{transform:translateY(-3px)}
body.fx-account .tool:nth-child(1){background:linear-gradient(140deg,#FF8A1F,#F25C54)!important}
body.fx-account .tool:nth-child(2){background:linear-gradient(140deg,#1F6B45,#3E9A5F)!important}
body.fx-account .tool:nth-child(3){background:linear-gradient(140deg,#7C3AED,#E8467C)!important}
body.fx-account .tool strong,body.fx-account .tool span{color:#fff!important}
body.fx-account .tool span{opacity:.92}
body.fx-account .tool em{background:#fff!important;color:var(--ink)!important;border-radius:999px;padding:7px 14px!important;font-style:normal;font-weight:700;display:inline-block;margin-top:10px}
body.fx-account .tabs{background:#fff;border:2px solid var(--pith);border-radius:999px;padding:4px}
body.fx-account .tabs button{border-radius:999px!important;font-weight:700}
body.fx-account .tabs button[aria-selected="true"]{background:var(--ink)!important;color:#fff!important}
body.fx-account .check{background:var(--peel);border-radius:12px;padding:10px 12px;margin:0 0 8px}
body.fx-account .docs li{border-radius:12px}
body.fx-account label{font-weight:700}

/* ---- CV Rewrite tool ---- */
body.fx-cv main section{background:transparent!important;border:0!important}
body.fx-cv main .wrap{max-width:1080px}
body.fx-cv #accountBar{margin-top:18px}
body.fx-cv .panel label{font-weight:700!important;font-size:14.5px!important;text-transform:none!important;letter-spacing:0!important;font-family:'DM Sans',sans-serif!important;margin-top:14px}
body.fx-cv .q{background:linear-gradient(160deg,#FFF3E2,#FFE9E2)!important;border:2px solid #FFD9C2!important;border-radius:18px!important;padding:16px!important}
body.fx-cv .design-card{border-radius:14px!important;overflow:hidden;box-shadow:0 4px 14px rgba(23,25,28,.08)}
body.fx-cv .previewbox{border-radius:16px!important;box-shadow:0 8px 24px rgba(23,25,28,.1)}
body.fx-cv .chip{border-radius:999px!important;font-weight:700}
body.fx-cv .chip.on{background:var(--ink)!important;border-color:var(--ink)!important}

/* ---- Interview Prep ---- */
body.fx-prep main.wizard{max-width:1080px;box-sizing:border-box;margin:6px auto 60px;padding:0 24px}
body.fx-prep .panel-intro{font-size:16px;color:#3F444B}
body.fx-prep .pricing-block,body.fx-prep .upload-block,body.fx-prep .consent-block,body.fx-prep .star-guide-callout{background:#FFFDF9!important;border:2px solid var(--pith)!important;border-radius:16px!important;padding:16px!important;box-shadow:none!important}
body.fx-prep .pricing-block{background:linear-gradient(140deg,#EAF7EF,#E3F1FF)!important;border:0!important}
body.fx-prep .upload-block{border-style:dashed!important;border-color:#F4C9A0!important;background:#FFF6EC!important}
body.fx-prep .form-grid label{font-weight:700;font-size:14.5px}
body.fx-prep .tooltip-trigger{background:var(--kq)!important;color:#fff!important}
body.fx-prep .site-footer{padding:20px}

/* ---- CV Rewrite landing page ---- */
body.fx-landing main>section{background:var(--cream)!important;border:0!important}
body.fx-landing main>section:nth-of-type(odd):not(.hero){background:#fff!important}
body.fx-landing section.hero{background:var(--hero)!important;position:relative;overflow:hidden}
body.fx-landing section.hero:before{content:"";position:absolute;width:380px;height:380px;right:-110px;top:-170px;border-radius:50%;background:#fff;opacity:.16}
body.fx-landing section.hero:after{content:"";display:block!important;position:absolute;width:200px;height:200px;left:40%;bottom:-130px;border-radius:50%;background:#FFB547;opacity:.35!important}
body.fx-landing section.hero .wrap{position:relative;z-index:1}
body.fx-landing section.hero h1{color:#fff!important}
body.fx-landing section.hero .eyebrow{display:inline-block;color:#fff!important;background:rgba(255,255,255,.2);border-radius:999px;padding:5px 12px}
body.fx-landing section.hero .lead,body.fx-landing section.hero .fine,body.fx-landing section.hero .muted{color:#FFF4EA!important}
body.fx-landing section.hero .price-flag{background:#fff!important;color:#B44E00!important}
body.fx-landing section.hero .btn.accent{background:#17191C!important;box-shadow:0 8px 20px rgba(0,0,0,.25)!important}
body.fx-landing section.hero .btn.ghost{background:rgba(255,255,255,.14)!important;color:#fff!important;border-color:rgba(255,255,255,.55)!important}
body.fx-landing .cq-hero-img{border-radius:22px!important;box-shadow:0 18px 40px rgba(0,0,0,.25);transform:rotate(2deg);border:6px solid #fff}
body.fx-landing .eyebrow{color:#B44E00!important;font-weight:700}
body.fx-landing .tile{border:1px solid var(--pith)!important;border-radius:20px!important;box-shadow:0 10px 26px rgba(23,25,28,.06)!important;background:#fff!important}
body.fx-landing .tile .n{display:inline-flex;align-items:center;justify-content:center;min-width:44px;height:44px;padding:0 8px;border-radius:13px;background:var(--badge);color:#fff!important;transform:rotate(-4deg);font-family:'Bricolage Grotesque',sans-serif}
body.fx-landing .tile .ic{color:#E8467C!important}
body.fx-landing .whatlist p{background:#fff;border:1px solid var(--pith)!important;border-radius:16px;padding:14px 16px!important;box-shadow:0 6px 18px rgba(23,25,28,.05)}
body.fx-landing .whatlist strong{color:#B44E00!important}
body.fx-landing .vcard{border-radius:18px!important}
body.fx-landing .bafig img{border-radius:14px;box-shadow:0 10px 26px rgba(23,25,28,.12)}
body.fx-landing .bafig.after .lbl{color:#E8467C!important}

body.fx-prep .form-grid label,body.fx-prep .record-btn{text-transform:none!important;letter-spacing:0!important}
body.fx .steps,body.fx .fx-steps{flex-wrap:nowrap!important}
body.fx-cv main>section{padding-top:8px!important}

/* ---- each app keeps its own colour: CV Rewrite orange, Interview Prep green, CV Builder orange-to-pink ---- */
body.fx-cv,body.fx-landing{--hero:linear-gradient(120deg,#FF9A2E 0%,#FF7F14 45%,#E2650B 100%);--badge:linear-gradient(135deg,#FF8A1F,#E2650B);--app:#FF8A1F}
body.fx-prep{--hero:linear-gradient(120deg,#3E9A5F 0%,#1F6B45 55%,#14492F 100%);--badge:linear-gradient(135deg,#3E9A5F,#1F6B45);--app:#3E9A5F}
body.fx-prep .fx-hero:after{background:#FFB547;opacity:.3}
body.fx-prep .fx-how li:nth-child(1) .d{background:#FFB547}
body.fx-cv .fx-hero:after,body.fx-landing section.hero:after{background:#F25C54!important;opacity:.28!important}
body.fx-landing .tile .ic,body.fx-landing .bafig.after .lbl{color:#E2650B!important}
/* legal pages */
body.fx-legal main{max-width:860px;margin:26px auto 60px!important;padding:0 20px!important}
body.fx-legal main .legal,body.fx-legal main.legal{background:#fff;border:1px solid var(--pith);border-radius:20px;padding:26px 30px!important;box-shadow:0 10px 30px rgba(23,25,28,.06)}
body.fx-legal main.legal{max-width:860px}
body.fx-legal .legal h2{font-size:21px!important;margin-top:26px}
@media (max-width:640px){body.fx-legal main .legal,body.fx-legal main.legal{padding:18px 16px!important}}

/* Interview Prep header in the same 1080px container as the other Comquat pages */
body.fx-prep .site-header{padding-left:max(24px,calc((100% - 1032px) / 2))!important;padding-right:max(24px,calc((100% - 1032px) / 2))!important}
@media (max-width:1599px){body.fx-prep .cq-links a.cq-book{right:max(20px,calc((100% - 1032px) / 2))!important}}
@media (max-width:700px){body.fx .fx-hero-in{padding:24px 18px 22px}}

public/css/master.css.full:
/* The CV builder (master CV). Bright and friendly, built for first CVs. */
:root{--sun:#FFB547;--coral:#F25C54;--sky:#2B7BE4;--mint:#12A88A;--cream:#FFF8EE}
.mcv-body{background:var(--cream)}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}

/* ---- hero ---- */
.hero{background:linear-gradient(120deg,#7C3AED 0%,#B23FC4 50%,#E8467C 100%);color:#fff;position:relative;overflow:hidden}
.hero:before,.hero:after{content:"";position:absolute;border-radius:50%;opacity:.18;background:#fff}
.hero:before{width:340px;height:340px;right:-90px;top:-150px}
.hero:after{width:180px;height:180px;left:46%;bottom:-120px;background:var(--sun);opacity:.35}
.hero-in{max-width:1080px;box-sizing:border-box;margin:0 auto;padding:34px 24px 30px;display:flex;gap:28px;align-items:center;justify-content:space-between;position:relative;z-index:1}
.kicker{display:inline-block;font-weight:700;font-size:12.5px;letter-spacing:.12em;text-transform:uppercase;background:rgba(255,255,255,.2);border-radius:999px;padding:5px 12px;margin:0 0 10px}
.hero h1{color:#fff;font-size:clamp(34px,6vw,54px);margin:0 0 10px}
.hero-lede{font-size:17.5px;max-width:620px;margin:0 0 16px;color:#FFF4EA}
.hero-how{list-style:none;display:flex;flex-wrap:wrap;gap:10px;margin:0;padding:0}
.hero-how li{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);border-radius:999px;padding:6px 14px 6px 6px;font-weight:700;font-size:14.5px}
.hero-how .dot{width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;color:var(--ink)}
.dot.d1{background:var(--sun)}.dot.d2{background:#fff}.dot.d3{background:#A7F3D0}
.ring-wrap{position:relative;width:132px;height:132px;flex:0 0 132px;background:rgba(255,255,255,.14);border-radius:50%}
.ring{width:132px;height:132px;transform:rotate(-90deg)}
.ring circle{fill:none;stroke-width:11}
.ring-bg{stroke:rgba(255,255,255,.28)}
.ring-fg{stroke:#fff;stroke-linecap:round;stroke-dasharray:314.16;stroke-dashoffset:314.16;transition:stroke-dashoffset .6s ease}
.ring-num{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;line-height:1}
.ring-num strong{font-family:'Bricolage Grotesque',sans-serif;font-size:30px}
.ring-num span{font-size:13px;font-weight:700;margin-top:4px;opacity:.9}
@media (max-width:700px){.hero-how{display:none}.hero h1{font-size:34px}.hero-lede{font-size:15.5px;margin:0}.ring-wrap{width:96px;height:96px;flex-basis:96px}.ring{width:96px;height:96px}.ring-num strong{font-size:22px}.hero-in{padding:24px 18px 22px;align-items:flex-start}.hero-lede{font-size:16px}.hero-how li{font-size:13px}}

/* ---- page ---- */
.mcv-main{max-width:1080px;box-sizing:border-box;margin:0 auto 70px;padding:0 24px}
#loading,#signed-out{margin-top:28px}
.steps{display:flex;gap:8px;overflow-x:auto;padding:16px 2px 12px;margin:0 0 6px;scrollbar-width:thin;position:sticky;top:0;z-index:20;background:var(--cream)}
.stp{flex:0 0 auto;display:flex;align-items:center;gap:8px;border:2px solid var(--pith);background:#fff;border-radius:999px;padding:6px 14px 6px 6px;font:inherit;font-weight:700;font-size:14px;color:var(--ink);cursor:pointer;transition:transform .15s,border-color .15s}
.stp:hover{transform:translateY(-1px);border-color:var(--kq)}
.stp .n{width:26px;height:26px;border-radius:50%;background:var(--peel);display:inline-flex;align-items:center;justify-content:center;font-size:13px}
.stp.done .n{background:var(--leaf);color:#fff}
.stp.done .n:before{content:"✓"}
.stp.done .n span{display:none}
.stp[aria-current="step"]{background:var(--ink);color:#fff;border-color:var(--ink)}
.stp[aria-current="step"] .n{background:var(--kq);color:#fff}
.layout{display:grid;grid-template-columns:minmax(0,1fr) 400px;gap:24px;align-items:start}
@media (max-width:1100px){.layout{grid-template-columns:1fr}}
.col-form{min-width:0}

.step{display:none;background:#fff;border:1px solid var(--pith);border-radius:20px;padding:24px 26px;box-shadow:0 10px 30px rgba(23,25,28,.06);animation:stepIn .35s ease}
.step.on{display:block}
@keyframes stepIn{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.step h2{display:flex;align-items:center;gap:12px;font-size:27px;margin:0 0 12px}
.snum{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--kq),var(--coral));color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:19px;flex:0 0 38px;transform:rotate(-4deg)}
.mcv-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px 16px}
.mcv-grid .full{grid-column:1/-1}
@media (max-width:640px){.mcv-grid{grid-template-columns:1fr}.step{padding:18px 16px;border-radius:16px}.step h2{font-size:22px}}
.mcv-main label{display:block;font-weight:700;font-size:14.5px;margin:0 0 5px}
.mcv-main label small{font-weight:400;color:var(--muted)}
.mcv-main input[type=text],.mcv-main input[type=email],.mcv-main input[type=tel],.mcv-main input[type=url],.mcv-main textarea{width:100%;box-sizing:border-box;font:inherit;font-size:16px;padding:11px 13px;border:2px solid var(--pith);border-radius:12px;background:#fff;color:var(--ink);transition:border-color .15s,box-shadow .15s}
.mcv-main textarea{min-height:92px;resize:vertical;line-height:1.5}
.mcv-main input:focus,.mcv-main textarea:focus{outline:none;border-color:var(--kq);box-shadow:0 0 0 4px rgba(124,58,237,.18)}
.tip{font-size:15px;color:#3F444B;background:var(--peel);border-left:4px solid var(--kq);border-radius:0 12px 12px 0;padding:10px 14px;margin:0 0 14px}
.first-cv{border-left-color:var(--mint)!important;background:#E9FBF6!important}
.mcv-main h3.sub{font-family:'Bricolage Grotesque',sans-serif;font-size:19px;margin:22px 0 10px}
.small{font-size:14px;color:var(--muted)}

/* ---- buttons ---- */
.btn-spark{background:linear-gradient(120deg,#7C3AED,#E8467C);color:#fff;box-shadow:0 6px 16px rgba(124,58,237,.28)}
.btn-spark:hover{filter:brightness(1.06)}
.btn-spark svg,.btn-mic svg,.pv-fab svg{width:18px;height:18px;fill:currentColor}
.btn-spark.small-btn{padding:8px 14px;font-size:14px}
.btn-mic{display:inline-flex;align-items:center;gap:7px;border:2px solid var(--coral);background:#fff;color:#C2362E;border-radius:999px;padding:7px 14px;font:inherit;font-weight:700;font-size:14px;cursor:pointer}
.btn-mic:hover{background:#FFF0EF}
.btn-mic.rec{background:var(--coral);color:#fff;animation:pulse 1.2s infinite}
@keyframes pulse{0%{box-shadow:0 0 0 0 rgba(242,92,84,.5)}70%{box-shadow:0 0 0 12px rgba(242,92,84,0)}100%{box-shadow:0 0 0 0 rgba(242,92,84,0)}}
.mic-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:8px 0 0}
.mic-status{font-size:13.5px;color:var(--muted)}
.mic-status.err{color:#B3261E}
.build-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:18px 0 6px}
.add-btn{border:2px dashed var(--pith);background:transparent;border-radius:14px;padding:13px;width:100%;font:inherit;font-weight:700;color:var(--leaf);cursor:pointer;margin-top:4px}
.add-btn:hover{border-color:var(--leaf);background:#F4FAF6}
.icon-btn{border:1px solid var(--pith);background:#fff;border-radius:8px;padding:5px 10px;font:inherit;font-size:13px;cursor:pointer;color:var(--ink)}
.icon-btn:hover{border-color:var(--leaf)}
.icon-btn.del{color:#B3261E}

/* ---- writing styles ---- */
.style-box{border:2px solid #EDE4FF;background:#FAF7FF;border-radius:16px;padding:14px 16px;margin:0 0 18px}
.style-box h3.sub{margin:0 0 10px}
.styles{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
@media (max-width:640px){.styles{grid-template-columns:1fr}}
.style{border:2px solid #E4DAFB;background:#fff;border-radius:12px;padding:10px 12px;text-align:left;font:inherit;cursor:pointer;color:var(--ink)}
.style strong{display:block;font-size:15px}
.style span{display:block;font-size:13px;color:var(--muted);margin-top:2px}
.style em{display:block;font-size:13px;color:#5B21B6;margin-top:5px}
.style[aria-checked="true"]{border-color:#7C3AED;background:#F3EDFF;box-shadow:0 0 0 3px rgba(124,58,237,.15)}
.own-style{margin-top:10px}
.own-style summary{cursor:pointer;font-weight:700;color:#5B21B6;font-size:14.5px}

/* ---- question card ---- */
.qcard{border-radius:18px;padding:18px;background:linear-gradient(160deg,#FFF3E2,#FFE9E2);border:2px solid #FFD9C2;margin:0 0 6px}
.qtop{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:0 0 6px}
.qcount{font-weight:700;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:#B44E00}
.qdots{display:flex;gap:6px}
.qdot{width:12px;height:12px;border-radius:50%;border:2px solid #E7A877;background:#fff;cursor:pointer;padding:0}
.qdot.filled{background:var(--kq);border-color:var(--kq)}
.qdot.cur{transform:scale(1.3);border-color:var(--ink)}
.qcard h4{font-family:'Bricolage Grotesque',sans-serif;font-size:21px;margin:2px 0 4px;line-height:1.2}
.qcard .think{font-size:15px;color:#4A4F56;margin:0 0 10px}
.qcard details{margin:0 0 10px;font-size:14.5px}
.qcard details summary{cursor:pointer;font-weight:700;color:#B44E00}
.qcard details ul{margin:6px 0 0;padding-left:20px;color:#4A4F56}
.chips{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 10px}
.chip{border:2px solid var(--leaf);background:#fff;color:var(--leaf);border-radius:999px;padding:5px 12px;font:inherit;font-size:14px;font-weight:700;cursor:pointer;transition:transform .12s}
.chip:hover{background:#F4FAF6;transform:translateY(-1px)}
.qcard .eg-line{font-size:14px;color:var(--muted);font-style:italic;margin:8px 0 0}
.qnav{display:flex;justify-content:space-between;gap:8px;margin-top:12px}
.qnav button{border:0;background:none;font:inherit;font-weight:700;color:#B44E00;cursor:pointer;padding:6px 2px}
.qnav button[disabled]{opacity:.35;cursor:default}

.stmt-check{font-size:14px;margin:8px 0 0;color:var(--muted)}
.stmt-check.warn{color:#B44E00;font-weight:700}
.stmt-check.ok{color:var(--leaf);font-weight:700}
details.eg,details.ideas{margin:14px 0;border:1px solid var(--pith);border-radius:12px;padding:10px 14px;background:#fff;font-size:15px}
details.eg summary,details.ideas summary{cursor:pointer;font-weight:700;color:var(--leaf)}
details.eg .bad{margin:10px 0 6px;color:#7A2E2E}
details.eg .good{margin:0 0 6px;color:#14532D}
details.ideas ul{margin:8px 0;padding-left:20px}
details.ideas li{margin:0 0 4px}
.ai-note{font-size:13.5px;color:var(--muted);background:#FAF7FF;border-radius:10px;padding:10px 12px;margin:14px 0 0}

/* ---- strengths tiles ---- */
.beh-count{display:inline-block;font-weight:700;color:#fff;background:var(--leaf);border-radius:999px;padding:5px 14px;margin:0 0 12px;transition:background .2s}
.beh-count.none{background:var(--muted)}
.beh-count.many{background:#B44E00}
.beh-group{margin:0 0 16px}
.beh-group h4{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);margin:0 0 8px}
.beh-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
@media (max-width:640px){.beh-grid{grid-template-columns:1fr}}
.mcv-main label.beh{display:flex;gap:10px;align-items:flex-start;background:#fff;border:2px solid var(--pith);border-radius:14px;padding:11px 12px;cursor:pointer;font-size:15px;line-height:1.35;font-weight:500;margin:0;transition:transform .12s,border-color .15s,background .15s}
.mcv-main label.beh:hover{border-color:var(--kq);transform:translateY(-1px)}
.mcv-main label.beh input{position:absolute;opacity:0;width:1px;height:1px}
.beh .box{flex:0 0 24px;width:24px;height:24px;border-radius:8px;border:2px solid var(--pith);background:#fff;display:inline-flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:14px;transition:all .15s}
.mcv-main label.beh:has(input:checked){background:#EAF7EF;border-color:var(--leaf)}
.beh:has(input:checked) .box{background:var(--leaf);border-color:var(--leaf)}
.beh:has(input:checked) .box:before{content:"✓"}
.beh:has(input:focus-visible){outline:3px solid var(--kq);outline-offset:2px}
.beh.pop{animation:pop .3s ease}
@keyframes pop{50%{transform:scale(1.04)}}
.beh small{display:block;color:var(--leaf);font-weight:700;font-size:12.5px;margin-top:3px}

/* ---- list items ---- */
.item{border:2px solid var(--pith);border-radius:16px;padding:16px;margin:0 0 12px;background:#FFFDF9}
.item-head{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:0 0 10px}
.item-head strong{font-size:16px}
.item-tools{display:flex;gap:6px}
.about-box{grid-column:1/-1;background:#FFF6EC;border:2px dashed #F4C9A0;border-radius:14px;padding:12px}
.about-box label{color:#9A3412}
.about-acts{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:8px}

/* ---- designs ---- */
.fresh-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:0 0 14px}
@media (max-width:760px){.fresh-grid{grid-template-columns:repeat(2,1fr)}}
.fcard{border:3px solid transparent;border-radius:14px;background:#fff;padding:6px;cursor:pointer;font:inherit;text-align:center;box-shadow:0 4px 14px rgba(23,25,28,.08);transition:transform .15s}
.fcard:hover{transform:translateY(-2px)}
.fcard img{width:100%;aspect-ratio:210/297;object-fit:cover;object-position:top;border-radius:9px;display:block;margin:0 0 6px;background:#f6f1e8}
.fcard span{font-weight:700;font-size:14px;color:var(--ink)}
.fcard.sel{border-color:var(--kq)}
.dl-row{display:flex;gap:8px;flex-wrap:wrap;margin:6px 0 8px}
.more-designs{margin:16px 0;border:1px solid var(--pith);border-radius:12px;padding:10px 14px;background:#fff}
.more-designs summary{cursor:pointer;font-weight:700;color:var(--leaf)}
.kind-toggle{display:flex;gap:8px;margin:12px 0}
.kind{border:1.5px solid var(--pith);background:#fff;border-radius:999px;padding:7px 14px;font:inherit;font-weight:700;cursor:pointer}
.kind.on{background:var(--ink);color:#fff;border-color:var(--ink)}
.design-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:10px;margin:0 0 6px}
.dcard{border:2px solid var(--pith);border-radius:10px;background:#fff;padding:6px;cursor:pointer;text-align:center;font:inherit;font-size:12.5px;font-weight:700;color:var(--ink)}
.dcard img{width:100%;aspect-ratio:210/297;object-fit:cover;object-position:top;border-radius:6px;display:block;margin:0 0 5px;background:#f6f1e8}
.dcard.sel{border-color:var(--leaf);box-shadow:0 0 0 3px rgba(31,107,69,.18)}
.done-box{background:linear-gradient(140deg,#EAF7EF,#E3F1FF);border-radius:16px;padding:16px 18px;margin-top:18px}
.done-box h3.sub{margin-top:0}
.danger-zone{margin:4px 0 0;font-size:14px}

/* ---- step nav ---- */
.step-nav{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:16px 0 8px}
.step-nav .btn{min-width:110px}
.save-status{font-size:13.5px;color:var(--muted);text-align:center}
.save-status.err{color:#B3261E;font-weight:700}
.guide-note{font-size:14px;color:var(--muted);margin:14px 0 0}

/* ---- preview ---- */
.col-preview{position:sticky;top:70px}
.pv-card{background:#fff;border:1px solid var(--pith);border-radius:20px;padding:14px;box-shadow:0 10px 30px rgba(23,25,28,.08)}
.pv-head{display:flex;justify-content:space-between;align-items:center;margin:0 0 8px}
.pv-head strong{font-family:'Bricolage Grotesque',sans-serif;font-size:18px;display:flex;align-items:center;gap:8px}
.pv-head strong:before{content:"";width:9px;height:9px;border-radius:50%;background:#22C55E;box-shadow:0 0 0 4px rgba(34,197,94,.2)}
.pv-close{display:none;border:0;background:var(--peel);border-radius:999px;padding:6px 14px;font:inherit;font-weight:700;cursor:pointer}
.pv-designs{display:flex;gap:6px;flex-wrap:wrap;margin:0 0 10px}
.pvd{display:flex;align-items:center;gap:6px;border:2px solid var(--pith);background:#fff;border-radius:999px;padding:4px 11px 4px 5px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
.pvd i{width:16px;height:16px;border-radius:50%;display:inline-block}
.pvd[aria-checked="true"]{border-color:var(--ink);background:var(--ink);color:#fff}
.pv-frame{background:#EDE6DA;border-radius:12px;padding:10px;max-height:calc(100vh - 290px);min-height:300px;overflow:auto;position:relative}
.pv-scale{transform-origin:top left;width:794px;box-shadow:0 4px 18px rgba(0,0,0,.15);background:#fff}
.pv-frame iframe{width:794px;height:1123px;border:0;display:block;background:#fff}
#pv-thumb{width:100%;border-radius:6px;display:block}
.pv-note{margin:8px 0 0}
.pv-acts{display:flex;gap:8px;margin-top:10px}
.pv-acts .btn{flex:1}
.pv-fab{position:fixed;right:16px;bottom:16px;z-index:40;display:none;align-items:center;gap:8px;border:0;border-radius:999px;padding:13px 20px;background:var(--ink);color:#fff;font:inherit;font-weight:700;font-size:15.5px;box-shadow:0 8px 24px rgba(0,0,0,.25);cursor:pointer}
@media (max-width:1100px){
  .col-preview{display:none;position:fixed;inset:0;z-index:60;background:rgba(23,25,28,.55);padding:12px;top:0}
  .col-preview.open{display:block}
  .pv-card{max-width:520px;margin:0 auto;height:calc(100% - 4px);box-sizing:border-box;display:flex;flex-direction:column}
  .pv-frame{flex:1;max-height:none}
  .pv-close{display:inline-block}
  .pv-fab:not(.hidden){display:inline-flex}
  .steps{top:0}
}

/* ---- toast and confetti ---- */
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,40px);opacity:0;z-index:80;background:var(--ink);color:#fff;border-radius:999px;padding:12px 20px;font-weight:700;box-shadow:0 10px 30px rgba(0,0,0,.25);transition:all .3s;pointer-events:none;max-width:90vw;text-align:center}
.toast.on{opacity:1;transform:translate(-50%,0)}
.confetti{position:fixed;inset:0;pointer-events:none;z-index:79;overflow:hidden}
.confetti i{position:absolute;top:-12px;width:9px;height:14px;border-radius:2px;animation:fall 1.6s ease-in forwards}
@keyframes fall{to{transform:translateY(105vh) rotate(540deg);opacity:.9}}
@media (prefers-reduced-motion:reduce){.step,.beh.pop,.btn-mic.rec{animation:none}.confetti{display:none}.ring-fg{transition:none}}
.hidden{display:none!important}
/* CV Builder lead colour: purple to pink, matching its My account card */
.hero,.mcv-main,.layout{--kq:#7C3AED;--coral:#E8467C;--peel:#F3ECFF}
.hero:after{background:#FF9BC4}

accounts/public/account.css.full:
/* Comquat account pages. Tokens from the Comquat Brand design system:
   leaf #1F6B45, leaf-light #3E9A5F, kumquat #FF8A1F, kumquat-text #B44E00,
   ink #17191C, peel #FFF3E2, pith #E9DCC8, muted #5B5F66. */
:root{--leaf:#1F6B45;--leaf2:#3E9A5F;--kq:#FF8A1F;--kqt:#B44E00;--ink:#17191C;--peel:#FFF3E2;--pith:#E9DCC8;--muted:#5B5F66;--err:#A8321E}
*{box-sizing:border-box}
html,body{margin:0;background:var(--peel);color:var(--ink);font-family:'DM Sans',system-ui,-apple-system,sans-serif;font-size:16px;line-height:1.55}
a{color:var(--leaf)}
.cq-head{display:grid;grid-template-columns:minmax(0,1fr);row-gap:14px;padding:18px max(24px,calc((100% - 1032px) / 2)) 14px;border-bottom:1px solid var(--pith);background:#fff;position:relative}
.cq-head .cq-book{position:absolute;top:18px;right:max(24px,calc((100% - 1032px) / 2));background:#FF8A1F;color:#17191C;font-weight:700;font-size:13px;letter-spacing:.04em;text-transform:uppercase;text-decoration:none;padding:8px 16px;border-radius:999px;line-height:1.2;white-space:nowrap}
.cq-head .cq-book:hover{background:#E2650B}
@media (max-width:480px){.cq-head .cq-book{font-size:11.5px;padding:7px 11px;top:20px;right:16px}}
.cq-head .cq-brand{justify-self:start}
.cq-brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;line-height:1}
.cq-brand img{height:32px;width:auto;display:block}
.cq-feat{font-weight:700;font-size:12px;letter-spacing:.12em;text-transform:uppercase;padding:6px 12px;border-radius:999px;background:var(--ink);color:var(--peel)}
.cq-head nav{display:flex;align-items:center;flex-wrap:wrap;gap:8px 16px;font-size:13.5px;font-weight:500;letter-spacing:.04em;text-transform:uppercase}
.cq-head nav a{color:var(--muted);text-decoration:none;white-space:nowrap}
.cq-head nav a.active{color:var(--leaf)}
.cq-head nav .linkbtn{font:inherit;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}
@media (max-width:760px){.cq-head nav{flex-wrap:nowrap;overflow-x:auto;gap:18px;padding-bottom:4px;-webkit-overflow-scrolling:touch;scrollbar-width:none}.cq-head nav::-webkit-scrollbar{display:none}}
@media (max-width:480px){.cq-head .cq-feat{display:none}}
.cq-head nav a:hover{color:var(--leaf)}
main{max-width:620px;margin:40px auto 64px;padding:0 20px}
main.wide{max-width:760px}
h1{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-weight:800;font-size:clamp(30px,5vw,42px);letter-spacing:-.02em;line-height:1.08;margin:0 0 10px}
h2{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-weight:800;font-size:22px;letter-spacing:-.01em;margin:0 0 6px}
.lede{color:var(--muted);margin:0 0 26px;font-size:17px}
.card{background:#fff;border:1px solid var(--pith);border-radius:16px;padding:26px;margin:0 0 20px}
.tabs{display:flex;gap:6px;background:#fff;border:1px solid var(--pith);border-radius:999px;padding:5px;margin:0 0 20px;width:max-content}
.tabs button{border:0;background:none;font:inherit;font-weight:700;font-size:14.5px;padding:8px 18px;border-radius:999px;cursor:pointer;color:var(--muted)}
.tabs button[aria-selected="true"]{background:var(--leaf);color:var(--peel)}
label{display:block;font-weight:700;font-size:14px;margin:0 0 16px}
label .hint{display:block;font-weight:400;color:var(--muted);font-size:13.5px;margin-top:2px}
input[type=text],input[type=email],input[type=password]{display:block;width:100%;margin-top:6px;padding:12px 14px;font:inherit;font-weight:400;border:1.5px solid var(--pith);border-radius:10px;background:#fff;color:var(--ink)}
input:focus,button:focus-visible,a:focus-visible{outline:3px solid var(--leaf2);outline-offset:2px}
.check{display:flex;gap:12px;align-items:flex-start;font-weight:400;font-size:15px;margin:0 0 12px;cursor:pointer}
.check input{width:20px;height:20px;margin:2px 0 0;accent-color:var(--leaf);flex:0 0 auto}
.check strong{font-weight:700}
fieldset{border:0;margin:6px 0 18px;padding:0}
legend{font-weight:700;font-size:14px;margin:0 0 10px;padding:0}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:0;border-radius:6px;padding:12px 22px;font:inherit;font-weight:700;font-size:16px;cursor:pointer;text-decoration:none;box-shadow:0 2px 0 rgba(23,25,28,.18)}
.btn-primary{background:var(--leaf);color:var(--peel)}
.btn-primary:hover{background:#17573a}
.btn-ghost{background:#fff;color:var(--ink);border:1.5px solid var(--pith);box-shadow:none}
.btn-ghost:hover{border-color:var(--leaf);color:var(--leaf)}
.btn-danger{background:#fff;color:var(--err);border:1.5px solid var(--err);box-shadow:none}
.btn[disabled]{opacity:.55;cursor:wait}
.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.linkbtn{background:none;border:0;padding:0;font:inherit;color:var(--leaf);text-decoration:underline;cursor:pointer}
.msg{border-radius:10px;padding:12px 14px;margin:0 0 18px;font-size:15px}
.msg.ok{background:#E6F2EA;color:#174F33}
.msg.err{background:#FBE9E4;color:var(--err)}
.msg:empty{display:none}
.small{font-size:14px;color:var(--muted)}
.note{border-left:4px solid var(--kq);background:#fff;padding:14px 16px;border-radius:0 10px 10px 0;font-size:15px;margin:0 0 20px}
.kv{display:grid;grid-template-columns:120px 1fr;gap:6px 14px;margin:0 0 6px;font-size:15px}
.kv dt{color:var(--muted)}.kv dd{margin:0;font-weight:500;word-break:break-all}
.soon li{margin:0 0 6px}
.tool-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 0}
.tool{display:flex;flex-direction:column;gap:6px;background:var(--peel);border:1px solid var(--pith);border-radius:14px;padding:16px;color:var(--ink);text-decoration:none}
a.tool:hover{border-color:var(--leaf);box-shadow:0 4px 14px rgba(31,107,69,.12)}
.tool strong{font-family:'Bricolage Grotesque','DM Sans',sans-serif;font-size:18px;color:var(--leaf)}
.tool span{font-size:14.5px;color:var(--muted);flex:1}
.tool em{font-style:normal;font-weight:700;font-size:14.5px;align-self:flex-start;background:var(--leaf);color:#fff;border-radius:999px;padding:8px 14px;margin-top:4px}
.tool-soon{opacity:.85}
.soon-tag{display:inline-block;margin-left:4px;font-family:'DM Sans',sans-serif;font-size:10.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--kqt);border:1px solid var(--kq);border-radius:999px;padding:1px 7px;vertical-align:3px;background:#fff}
@media (max-width:720px){.tool-grid{grid-template-columns:1fr}}
.docs{list-style:none;margin:14px 0 0;padding:0}
.docs li{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap;padding:14px 0;border-top:1px solid var(--pith)}
.docs li:first-child{border-top:0;padding-top:4px}
.docs .doc-kind{display:inline-block;font-size:11.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--leaf);margin:0 0 2px}
.docs .doc-title{display:block;font-weight:700;font-size:15.5px}
.docs .doc-meta{display:block;font-size:13.5px;color:var(--muted)}
.docs .doc-actions{display:flex;gap:10px;align-items:center}
.docs .btn{padding:8px 14px;font-size:14px}
.hidden{display:none!important}
footer{text-align:center;font-size:13.5px;color:var(--muted);padding:0 20px 40px}
@media (max-width:560px){.card{padding:20px}.tabs{width:100%}.tabs button{flex:1;padding:8px 10px}}
.sep{border:0;border-top:1px solid var(--pith);margin:24px 0}

accounts/public/fresh.css.full:
/* Comquat "fresh" look: the bright style first made for the CV builder, shared by
   CV Rewrite, Interview Prep and the account pages. Served at /account/fresh.css
   by both apps. Load it LAST: every rule is scoped to body.fx so it wins over the
   older page themes. */
body.fx{--kq:#FF8A1F;--coral:#F25C54;--pink:#E8467C;--sun:#FFB547;--leaf:#1F6B45;--ink:#17191C;--peel:#FFF3E2;--pith:#E9DCC8;--cream:#FFF8EE;--muted:#5B5F66;--violet:#7C3AED;
  background:var(--cream)!important;color:var(--ink)!important;font-family:'DM Sans',system-ui,-apple-system,sans-serif!important}
body.fx h1,body.fx h2,body.fx h3{font-family:'Bricolage Grotesque','DM Sans',sans-serif!important;color:var(--ink)!important;letter-spacing:-.01em}
body.fx main a{color:#B44E00}

/* ---- the banner ---- */
body.fx{--hero:linear-gradient(120deg,#FF8A1F 0%,#F25C54 55%,#E8467C 100%);--badge:linear-gradient(135deg,#FF8A1F,#F25C54);--app:#FF8A1F}
body.fx .fx-hero{padding:0!important;margin:0!important;background:var(--hero)!important;color:#fff!important;position:relative;overflow:hidden;border:0!important}
body.fx .fx-hero:before,body.fx .fx-hero:after{content:"";position:absolute;border-radius:50%;pointer-events:none}
body.fx .fx-hero:before{width:340px;height:340px;right:-90px;top:-150px;background:#fff;opacity:.18}
body.fx .fx-hero:after{width:180px;height:180px;left:46%;bottom:-120px;background:var(--sun);opacity:.35}
body.fx .fx-hero-in{max-width:1080px;box-sizing:border-box;margin:0 auto;padding:34px 24px 30px;position:relative;z-index:1}
body.fx .fx-kicker{display:inline-block;font-weight:700;font-size:12.5px;letter-spacing:.12em;text-transform:uppercase;background:rgba(255,255,255,.2);border-radius:999px;padding:5px 12px;margin:0 0 10px;color:#fff}
body.fx .fx-hero h1{color:#fff!important;font-size:clamp(34px,6vw,54px)!important;font-weight:800!important;line-height:1.05!important;margin:0 0 10px!important}
body.fx .fx-hero p{color:#FFF4EA!important}
body.fx .fx-lede{font-size:17.5px;max-width:640px;margin:0 0 16px}
body.fx .fx-how{list-style:none;display:flex;flex-wrap:wrap;gap:10px;margin:0;padding:0}
body.fx .fx-how li{display:flex;align-items:center;gap:8px;background:rgba(255,255,255,.16);border:1px solid rgba(255,255,255,.3);border-radius:999px;padding:6px 14px 6px 6px;font-weight:700;font-size:14.5px;color:#fff}
body.fx .fx-how .d{width:26px;height:26px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;font-size:13px;color:var(--ink);background:var(--sun)}
body.fx .fx-how li:nth-child(2) .d{background:#fff}
body.fx .fx-how li:nth-child(3) .d{background:#A7F3D0}
body.fx .fx-how li:nth-child(4) .d{background:#C4B5FD}
body.fx .fx-hero-sm .fx-hero-in{padding:26px 24px 24px}
body.fx .fx-hero-sm h1{font-size:clamp(30px,5vw,44px)!important}
@media (max-width:700px){body.fx .fx-how{display:none}body.fx .fx-hero h1{font-size:34px!important}body.fx .fx-lede{font-size:15.5px;margin:0}body.fx .fx-hero-in{padding:24px 18px 22px}}

/* ---- step chips ---- */
body.fx .fx-steps,body.fx .steps{display:flex!important;gap:8px!important;overflow-x:auto;padding:16px 2px 12px!important;margin:0 0 6px!important;scrollbar-width:thin;border:0!important;background:transparent!important}
body.fx .steps .s,body.fx .fx-steps .fx-s{flex:0 0 auto;display:flex;align-items:center;gap:8px;border:2px solid var(--pith)!important;background:#fff!important;border-radius:999px!important;padding:7px 16px!important;font-weight:700!important;font-size:14px!important;color:var(--ink)!important;letter-spacing:0!important;text-transform:none!important;font-family:'DM Sans',sans-serif!important;cursor:default}
body.fx .steps .s.done,body.fx .fx-steps .fx-s.done{border-color:var(--leaf)!important;color:var(--leaf)!important;cursor:pointer}
body.fx .steps .s.done:before,body.fx .fx-steps .fx-s.done:before{content:"✓";display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:var(--leaf);color:#fff;font-size:12px}
body.fx .steps .s.active,body.fx .fx-steps .fx-s.active{background:var(--ink)!important;color:#fff!important;border-color:var(--ink)!important}
body.fx .steps .s.active:before,body.fx .fx-steps .fx-s.active:before{content:"";width:10px;height:10px;border-radius:50%;background:var(--app)}

/* ---- cards ---- */
body.fx .panel,body.fx .fx-card,body.fx main .card{background:#fff!important;border:1px solid var(--pith)!important;border-radius:20px!important;padding:24px 26px!important;box-shadow:0 10px 30px rgba(23,25,28,.06)!important;color:var(--ink)!important}
@media (max-width:640px){body.fx .panel,body.fx .fx-card,body.fx main .card{padding:18px 16px!important;border-radius:16px!important}}
body.fx .panel h2,body.fx main .card>h2{display:flex;align-items:center;gap:12px;font-size:26px!important;font-weight:800!important;margin:0 0 10px!important}
body.fx .fx-num{width:38px;height:38px;border-radius:12px;background:var(--badge);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:19px;flex:0 0 38px;transform:rotate(-4deg);font-family:'Bricolage Grotesque',sans-serif}

/* ---- tips and notices ---- */
body.fx .notice,body.fx .fx-tip{background:var(--peel)!important;border:0!important;border-left:4px solid var(--kq)!important;border-radius:0 12px 12px 0!important;padding:11px 14px!important;color:#3F444B!important}
body.fx .notice.hidden{display:none!important}

/* ---- form fields ---- */
body.fx input[type=text],body.fx input[type=email],body.fx input[type=url],body.fx input[type=tel],body.fx input[type=password],body.fx textarea,body.fx select{width:100%;box-sizing:border-box;font:inherit!important;font-size:16px!important;padding:11px 13px!important;border:2px solid var(--pith)!important;border-radius:12px!important;background:#fff!important;color:var(--ink)!important;transition:border-color .15s,box-shadow .15s}
body.fx input:focus,body.fx textarea:focus,body.fx select:focus{outline:none!important;border-color:var(--kq)!important;box-shadow:0 0 0 4px rgba(255,138,31,.18)!important}
body.fx input[type=file]{font:inherit;font-size:14px;padding:10px;border:2px dashed #F4C9A0;border-radius:12px;background:#FFF6EC;width:100%;box-sizing:border-box;color:var(--muted)}
body.fx input[type=file]::file-selector-button{border:0;border-radius:999px;background:var(--ink);color:#fff;font:inherit;font-weight:700;padding:7px 14px;margin-right:10px;cursor:pointer}
body.fx details>summary{cursor:pointer;font-weight:700!important;color:var(--leaf)!important;font-family:'DM Sans',sans-serif!important;text-transform:none!important;letter-spacing:0!important;font-size:15px!important}

/* ---- buttons ---- */
body.fx .btn,body.fx .btn-primary,body.fx .btn-secondary{border-radius:999px!important;font-weight:700!important;font-family:'DM Sans',sans-serif!important;letter-spacing:0!important;text-transform:none!important}
body.fx .btn.accent,body.fx main .btn-primary,body.fx .panel .btn-primary,body.fx .btn:not(.ghost):not(.btn-ghost):not(.btn-danger){background:var(--leaf)!important;color:#fff!important;border:0!important;box-shadow:0 6px 16px rgba(31,107,69,.22)!important;padding:12px 22px!important}
body.fx .btn.accent:hover,body.fx main .btn-primary:hover{background:#17573a!important}
body.fx .btn.ghost,body.fx .btn-ghost,body.fx .btn-secondary{background:#fff!important;color:var(--ink)!important;border:2px solid var(--pith)!important;box-shadow:none!important}
body.fx .btn.ghost:hover,body.fx .btn-ghost:hover,body.fx .btn-secondary:hover{border-color:var(--leaf)!important;color:var(--leaf)!important}
body.fx .fx-spark{background:linear-gradient(120deg,var(--violet),var(--pink))!important;color:#fff!important;box-shadow:0 6px 16px rgba(124,58,237,.28)!important;border:0!important}
/* record buttons */
body.fx .record-btn,body.fx [data-rec]{display:inline-flex!important;align-items:center;gap:6px;border:2px solid var(--coral)!important;background:#fff!important;color:#C2362E!important;border-radius:999px!important;padding:7px 14px!important;font:inherit!important;font-weight:700!important;font-size:14px!important;cursor:pointer;box-shadow:none!important}
body.fx .record-btn:hover,body.fx [data-rec]:hover{background:#FFF0EF!important}
body.fx .record-btn.recording,body.fx .record-btn.is-recording{background:var(--coral)!important;color:#fff!important}

/* ---- footer ---- */
body.fx footer,body.fx .site-footer{background:transparent}

/* ---- shared layout bits ---- */
body.fx .fx-wrap{max-width:1080px;box-sizing:border-box;margin:0 auto;padding:0 24px}
body.fx .fx-hero .lede{color:#FFF4EA!important;font-size:17.5px;max-width:640px;margin:0}

/* ---- My account and sign-in ---- */
body.fx-account main{margin-top:26px}
body.fx-account .tools .tool-grid{gap:12px}
body.fx-account .tool{border:0!important;border-radius:18px!important;padding:16px!important;color:#fff!important;box-shadow:0 8px 22px rgba(23,25,28,.12);transition:transform .15s}
body.fx-account .tool:hover{transform:translateY(-3px)}
body.fx-account .tool:nth-child(1){background:linear-gradient(140deg,#FF8A1F,#F25C54)!important}
body.fx-account .tool:nth-child(2){background:linear-gradient(140deg,#1F6B45,#3E9A5F)!important}
body.fx-account .tool:nth-child(3){background:linear-gradient(140deg,#7C3AED,#E8467C)!important}
body.fx-account .tool strong,body.fx-account .tool span{color:#fff!important}
body.fx-account .tool span{opacity:.92}
body.fx-account .tool em{background:#fff!important;color:var(--ink)!important;border-radius:999px;padding:7px 14px!important;font-style:normal;font-weight:700;display:inline-block;margin-top:10px}
body.fx-account .tabs{background:#fff;border:2px solid var(--pith);border-radius:999px;padding:4px}
body.fx-account .tabs button{border-radius:999px!important;font-weight:700}
body.fx-account .tabs button[aria-selected="true"]{background:var(--ink)!important;color:#fff!important}
body.fx-account .check{background:var(--peel);border-radius:12px;padding:10px 12px;margin:0 0 8px}
body.fx-account .docs li{border-radius:12px}
body.fx-account label{font-weight:700}

/* ---- CV Rewrite tool ---- */
body.fx-cv main section{background:transparent!important;border:0!important}
body.fx-cv main .wrap{max-width:1080px}
body.fx-cv #accountBar{margin-top:18px}
body.fx-cv .panel label{font-weight:700!important;font-size:14.5px!important;text-transform:none!important;letter-spacing:0!important;font-family:'DM Sans',sans-serif!important;margin-top:14px}
body.fx-cv .q{background:linear-gradient(160deg,#FFF3E2,#FFE9E2)!important;border:2px solid #FFD9C2!important;border-radius:18px!important;padding:16px!important}
body.fx-cv .design-card{border-radius:14px!important;overflow:hidden;box-shadow:0 4px 14px rgba(23,25,28,.08)}
body.fx-cv .previewbox{border-radius:16px!important;box-shadow:0 8px 24px rgba(23,25,28,.1)}
body.fx-cv .chip{border-radius:999px!important;font-weight:700}
body.fx-cv .chip.on{background:var(--ink)!important;border-color:var(--ink)!important}

/* ---- Interview Prep ---- */
body.fx-prep main.wizard{max-width:1080px;box-sizing:border-box;margin:6px auto 60px;padding:0 24px}
body.fx-prep .panel-intro{font-size:16px;color:#3F444B}
body.fx-prep .pricing-block,body.fx-prep .upload-block,body.fx-prep .consent-block,body.fx-prep .star-guide-callout{background:#FFFDF9!important;border:2px solid var(--pith)!important;border-radius:16px!important;padding:16px!important;box-shadow:none!important}
body.fx-prep .pricing-block{background:linear-gradient(140deg,#EAF7EF,#E3F1FF)!important;border:0!important}
body.fx-prep .upload-block{border-style:dashed!important;border-color:#F4C9A0!important;background:#FFF6EC!important}
body.fx-prep .form-grid label{font-weight:700;font-size:14.5px}
body.fx-prep .tooltip-trigger{background:var(--kq)!important;color:#fff!important}
body.fx-prep .site-footer{padding:20px}

/* ---- CV Rewrite landing page ---- */
body.fx-landing main>section{background:var(--cream)!important;border:0!important}
body.fx-landing main>section:nth-of-type(odd):not(.hero){background:#fff!important}
body.fx-landing section.hero{background:var(--hero)!important;position:relative;overflow:hidden}
body.fx-landing section.hero:before{content:"";position:absolute;width:380px;height:380px;right:-110px;top:-170px;border-radius:50%;background:#fff;opacity:.16}
body.fx-landing section.hero:after{content:"";display:block!important;position:absolute;width:200px;height:200px;left:40%;bottom:-130px;border-radius:50%;background:#FFB547;opacity:.35!important}
body.fx-landing section.hero .wrap{position:relative;z-index:1}
body.fx-landing section.hero h1{color:#fff!important}
body.fx-landing section.hero .eyebrow{display:inline-block;color:#fff!important;background:rgba(255,255,255,.2);border-radius:999px;padding:5px 12px}
body.fx-landing section.hero .lead,body.fx-landing section.hero .fine,body.fx-landing section.hero .muted{color:#FFF4EA!important}
body.fx-landing section.hero .price-flag{background:#fff!important;color:#B44E00!important}
body.fx-landing section.hero .btn.accent{background:#17191C!important;box-shadow:0 8px 20px rgba(0,0,0,.25)!important}
body.fx-landing section.hero .btn.ghost{background:rgba(255,255,255,.14)!important;color:#fff!important;border-color:rgba(255,255,255,.55)!important}
body.fx-landing .cq-hero-img{border-radius:22px!important;box-shadow:0 18px 40px rgba(0,0,0,.25);transform:rotate(2deg);border:6px solid #fff}
body.fx-landing .eyebrow{color:#B44E00!important;font-weight:700}
body.fx-landing .tile{border:1px solid var(--pith)!important;border-radius:20px!important;box-shadow:0 10px 26px rgba(23,25,28,.06)!important;background:#fff!important}
body.fx-landing .tile .n{display:inline-flex;align-items:center;justify-content:center;min-width:44px;height:44px;padding:0 8px;border-radius:13px;background:var(--badge);color:#fff!important;transform:rotate(-4deg);font-family:'Bricolage Grotesque',sans-serif}
body.fx-landing .tile .ic{color:#E8467C!important}
body.fx-landing .whatlist p{background:#fff;border:1px solid var(--pith)!important;border-radius:16px;padding:14px 16px!important;box-shadow:0 6px 18px rgba(23,25,28,.05)}
body.fx-landing .whatlist strong{color:#B44E00!important}
body.fx-landing .vcard{border-radius:18px!important}
body.fx-landing .bafig img{border-radius:14px;box-shadow:0 10px 26px rgba(23,25,28,.12)}
body.fx-landing .bafig.after .lbl{color:#E8467C!important}

body.fx-prep .form-grid label,body.fx-prep .record-btn{text-transform:none!important;letter-spacing:0!important}
body.fx .steps,body.fx .fx-steps{flex-wrap:nowrap!important}
body.fx-cv main>section{padding-top:8px!important}

/* ---- each app keeps its own colour: CV Rewrite orange, Interview Prep green, CV Builder orange-to-pink ---- */
body.fx-cv,body.fx-landing{--hero:linear-gradient(120deg,#FF9A2E 0%,#FF7F14 45%,#E2650B 100%);--badge:linear-gradient(135deg,#FF8A1F,#E2650B);--app:#FF8A1F}
body.fx-prep{--hero:linear-gradient(120deg,#3E9A5F 0%,#1F6B45 55%,#14492F 100%);--badge:linear-gradient(135deg,#3E9A5F,#1F6B45);--app:#3E9A5F}
body.fx-prep .fx-hero:after{background:#FFB547;opacity:.3}
body.fx-prep .fx-how li:nth-child(1) .d{background:#FFB547}
body.fx-cv .fx-hero:after,body.fx-landing section.hero:after{background:#F25C54!important;opacity:.28!important}
body.fx-landing .tile .ic,body.fx-landing .bafig.after .lbl{color:#E2650B!important}
/* legal pages */
body.fx-legal main{max-width:860px;margin:26px auto 60px!important;padding:0 20px!important}
body.fx-legal main .legal,body.fx-legal main.legal{background:#fff;border:1px solid var(--pith);border-radius:20px;padding:26px 30px!important;box-shadow:0 10px 30px rgba(23,25,28,.06)}
body.fx-legal main.legal{max-width:860px}
body.fx-legal .legal h2{font-size:21px!important;margin-top:26px}
@media (max-width:640px){body.fx-legal main .legal,body.fx-legal main.legal{padding:18px 16px!important}}

/* Interview Prep header in the same 1080px container as the other Comquat pages */
body.fx-prep .site-header{padding-left:max(24px,calc((100% - 1032px) / 2))!important;padding-right:max(24px,calc((100% - 1032px) / 2))!important}
@media (max-width:1599px){body.fx-prep .cq-links a.cq-book{right:max(20px,calc((100% - 1032px) / 2))!important}}
@media (max-width:700px){body.fx .fx-hero-in{padding:24px 18px 22px}}

cp2.css.full:
/* The Com'mon People - 2026 redesign system (Option B).  One stylesheet, all pages. */
:root{
  --navy:#161F29; --cream:#ECE6D8; --gold:#E0B03C; --teal:#5AA9C2; --orange:#D2691E; --red:#C0392B;
  --ink:#1C2733; --muted:#5E6B77;
  --page:#FFFFFF; --card:#FFFFFF; --tint:#EAF2F5; --line:#E3E7EA;
  --primary:var(--navy); --on-primary:#fff; --accent:var(--teal);
  --radius:14px; --radius-lg:20px;
  --hero-bg:var(--navy); --hero-ink:var(--cream); --hero-mut:#AEBAC6;
  --shadow:0 18px 44px -22px rgba(22,31,41,.5);
  --display:"Anton","Arial Narrow",sans-serif;
  --label:"Oswald","Arial Narrow",sans-serif;
  --body:"Hanken Grotesk","Helvetica Neue",Arial,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--page);color:var(--ink);font-family:var(--body);font-size:17px;line-height:1.62;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img,svg{display:block;max-width:100%}
h1,h2,h3,h4{font-family:var(--display);font-weight:400;text-transform:uppercase;line-height:.98;letter-spacing:.4px;text-wrap:balance;margin:0}
.wrap{max-width:1200px;margin:0 auto;padding:0 30px}
.eyebrow{font-family:var(--label);font-weight:700;font-size:13px;letter-spacing:.16em;text-transform:uppercase;color:var(--accent)}
.mark-underline{position:relative;white-space:nowrap;z-index:0}
.mark-underline::after{content:"";position:absolute;left:-1px;right:-1px;bottom:.05em;height:.30em;background:var(--orange);opacity:.92;border-radius:3px;z-index:-1;transform:rotate(-1deg)}

/* license-plate logo */
.plates{display:inline-flex;gap:4px;align-items:center}
.plate{font-family:var(--display);color:#14110E;-webkit-text-stroke:3px #FBF7EC;paint-order:stroke fill;font-size:20px;line-height:1;padding:6px 10px 7px;border-radius:7px;border:2.5px solid #14110E;letter-spacing:1px;text-transform:uppercase;box-shadow:0 3px 0 rgba(20,17,14,.55)}
.plate.p1{background:var(--gold);transform:rotate(-3deg)}
.plate.p2{background:var(--teal);transform:rotate(2deg)}
.plate.p3{background:var(--orange);transform:rotate(-2deg)}
.plate.sm{font-size:15px;padding:4px 7px 5px}

/* stickers */
.sticker{display:inline-flex;align-items:center;gap:7px;font-family:var(--label);font-weight:700;text-transform:uppercase;font-size:12px;letter-spacing:.08em;color:#fff;background:var(--red);padding:8px 13px;border-radius:999px;transform:rotate(-3deg);box-shadow:0 8px 18px -8px rgba(192,57,43,.6)}
.sticker.orange{background:var(--orange)} .sticker.navy{background:var(--navy);color:var(--cream)}

/* buttons */
.btn{display:inline-flex;align-items:center;gap:9px;font-family:var(--label);font-weight:600;font-size:15px;letter-spacing:.02em;text-transform:uppercase;padding:14px 26px;border-radius:999px;border:2px solid transparent;background:var(--primary);color:var(--on-primary);cursor:pointer;transition:transform .12s ease,box-shadow .12s ease}
.btn:hover{transform:translateY(-2px);box-shadow:0 14px 26px -14px rgba(22,31,41,.7)}
.btn.lg{padding:16px 32px;font-size:16px}
.btn.ghost{background:transparent;color:var(--ink);border-color:var(--line)}
.btn.ghost:hover{border-color:var(--primary);color:var(--primary)}
.btn.orange{background:var(--orange);color:#fff} .btn.navy{background:var(--navy);color:var(--cream)} .btn.red{background:var(--red);color:#fff}
.btn.on-color{background:var(--cream);color:var(--navy)}
a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--orange);outline-offset:2px}

/* art panels */
.art{position:relative;border-radius:var(--radius-lg);overflow:hidden;background:linear-gradient(150deg,var(--teal),var(--navy));color:var(--cream);isolation:isolate;box-shadow:var(--shadow)}
.art.gold{background:linear-gradient(150deg,var(--gold),var(--orange))} .art.orange{background:linear-gradient(150deg,var(--orange),#a54a12)}
.art.navy{background:linear-gradient(150deg,#22303f,var(--navy))} .art.red{background:linear-gradient(150deg,#d85a4c,var(--red))} .art.teal{background:linear-gradient(150deg,var(--teal),#2f7f97)}
.art::after{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.16) 1px,transparent 1.6px);background-size:16px 16px;opacity:.45}
.art .ico{position:absolute;width:56%;height:56%;right:-6%;bottom:-8%;color:rgba(255,255,255,.18);z-index:0}
.art .cap{position:absolute;left:20px;top:18px;font-family:var(--label);font-weight:700;font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.72);z-index:2}
.art .ico-lead{position:absolute;left:20px;bottom:18px;width:58px;height:58px;color:rgba(255,255,255,.92);z-index:2}

/* nav */
.nav{position:sticky;top:0;z-index:60;background:color-mix(in srgb,var(--page) 88%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
.nav .row{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 0}
.links{display:flex;gap:22px;font-family:var(--label);font-weight:600;font-size:14px;text-transform:uppercase;letter-spacing:.03em}
.links a{color:var(--muted)} .links a:hover,.links a[aria-current]{color:var(--orange)}
.nav-actions{display:flex;align-items:center;gap:10px}
.burger{display:none;background:transparent;border:2px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer;color:var(--ink)}
.burger svg{width:20px;height:20px}

/* sections */
section{padding:84px 0}
section.tight{padding:60px 0}
.band-tint{background:var(--tint)} .band-navy{background:var(--navy);color:var(--cream)} .band-teal{background:var(--teal);color:#0F3038} .band-orange{background:var(--orange);color:#2A1408}
.band-navy h2,.band-navy h3{color:var(--cream)} .band-teal h2,.band-teal h3{color:#0F3038} .band-orange h2,.band-orange h3{color:#2A1408}
.band-navy .eyebrow{color:var(--gold)} .band-teal .eyebrow{color:var(--navy)} .band-orange .eyebrow{color:var(--navy)}
.head{max-width:760px;margin-bottom:42px}
.head .eyebrow{margin-bottom:14px;display:inline-block}
.head h2{font-size:clamp(32px,4.8vw,52px)}
.head p{color:var(--muted);font-size:18px;margin:14px 0 0}
.band-navy .head p{color:#AEBAC6}

/* hero */
.hero{background:var(--hero-bg);color:var(--hero-ink);padding:74px 0 66px;border-bottom:1px solid var(--line)}
.hero h1,.hero h2{color:var(--hero-ink)}
.hero .grid{display:grid;grid-template-columns:1.06fr .94fr;gap:52px;align-items:center}
.hero h1{font-size:clamp(48px,7.4vw,92px);letter-spacing:.5px}
.hero .lead{color:var(--hero-mut);font-size:18.5px;max-width:50ch;margin:22px 0 10px}
.hero .lead.two{font-size:16.5px;margin-top:10px}
.hero .cta{display:flex;gap:14px;flex-wrap:wrap;margin-top:26px;align-items:center}
.hero-art{aspect-ratio:1/1;min-height:380px}
.hero-art .sticker{position:absolute;z-index:3}.hero-art .s1{right:16px;top:16px}.hero-art .s2{left:16px;bottom:16px}
.trust{display:flex;gap:28px;flex-wrap:wrap;margin-top:30px;font-family:var(--label);font-weight:600;font-size:12.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--hero-mut)}
.trust b{color:var(--gold);font-size:16px;font-family:var(--display);margin-right:4px}

/* ticker */
.ticker{overflow:hidden;background:var(--orange);border-top:3px solid #14110E;border-bottom:3px solid #14110E}
.ticker .track{display:flex;width:max-content;animation:marq 34s linear infinite}
.ticker:hover .track{animation-play-state:paused}
.ticker .seg{display:flex;align-items:center;gap:34px;padding:13px 18px;font-family:var(--display);font-size:26px;text-transform:uppercase;letter-spacing:.6px;color:#241203;white-space:nowrap}
.ticker .seg i{font-style:normal;font-size:20px;color:#14110E}
@keyframes marq{to{transform:translateX(-50%)}}

/* scrolling covers */
.scroller{overflow:hidden;padding:8px 0}
.scroller .strip{display:flex;gap:20px;width:max-content;padding:0 30px;animation:marq 60s linear infinite}
.scroller:hover .strip{animation-play-state:paused}
.cover{position:relative;flex:0 0 300px;height:196px;border-radius:var(--radius-lg);border:2.5px solid #14110E;overflow:hidden;box-shadow:var(--shadow);display:block;isolation:isolate}
.cover:nth-child(odd){transform:rotate(-1.3deg)}.cover:nth-child(even){transform:rotate(1.3deg)}
.cover::after{content:"";position:absolute;inset:0;background-image:radial-gradient(rgba(255,255,255,.16) 1px,transparent 1.6px);background-size:16px 16px;opacity:.45}
.cover .ico{position:absolute;width:52%;height:52%;right:-4%;bottom:-6%;color:rgba(255,255,255,.18);z-index:0}
.cover .cover-tag{position:absolute;left:16px;top:14px;font-family:var(--label);font-weight:700;font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:rgba(255,255,255,.85);z-index:2}
.cover h4{position:absolute;left:16px;right:16px;bottom:14px;color:#fff;font-family:var(--display);font-size:20px;line-height:.98;text-transform:uppercase;z-index:2;text-shadow:0 2px 10px rgba(0,0,0,.45)}

/* cards */
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.cards.two{grid-template-columns:repeat(2,1fr)} .cards.four{grid-template-columns:repeat(4,1fr)}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius-lg);overflow:hidden;display:flex;flex-direction:column;box-shadow:var(--shadow)}
.card .top{aspect-ratio:16/10;position:relative}
.card .in{padding:24px 24px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.card h3{font-size:23px} .card p{color:var(--muted);font-size:15px;margin:0}
.card .foot{margin-top:auto;padding-top:14px;display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line)}
.card .go{font-family:var(--label);font-weight:700;font-size:13px;text-transform:uppercase;letter-spacing:.04em;color:var(--orange);display:inline-flex;gap:7px;align-items:center}
.card .tag{font-family:var(--label);font-weight:700;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.card .tag.free{color:var(--teal)} .card .tag.paid{color:var(--orange)}

/* feature split */
.feature{display:grid;grid-template-columns:1fr 1fr;gap:36px;align-items:center}
.feature .art{aspect-ratio:4/3;min-height:300px}
.feature.alt .txt{order:2}.feature.alt .art{order:1}
.feature .txt h2{font-size:clamp(30px,4.2vw,46px)}
.feature .txt p{color:var(--muted);font-size:17px;margin:16px 0 0}
.band-navy .feature .txt p{color:#C6CFD8}.band-teal .feature .txt p{color:#123842}.band-orange .feature .txt p{color:#3a2110}
.feature .cta{margin-top:24px;display:flex;gap:14px;flex-wrap:wrap;align-items:center}

/* prices */
.prices{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:6px;max-width:520px}
.prices.two{grid-template-columns:repeat(2,1fr)}
.price{border:1.5px solid var(--line);border-radius:var(--radius);padding:18px 14px;text-align:center;background:var(--card)}
.band-navy .price{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.22)}
.price .l{font-family:var(--label);font-weight:700;font-size:11px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.band-navy .price .l{color:#AEBAC6}
.price .v{font-family:var(--display);font-size:33px;color:var(--orange);margin-top:4px}
.band-navy .price .v{color:var(--gold)}
.price .s{font-size:11px;color:var(--muted);margin-top:2px}.band-navy .price .s{color:#AEBAC6}

/* prose (articles) */
.prose{max-width:760px;margin:0 auto} .prose.wide{max-width:900px}
.prose p{font-size:17.5px;line-height:1.75;margin:0 0 20px;color:var(--ink)}
.prose h2{font-size:clamp(26px,3.4vw,38px);margin:38px 0 14px}
.prose h3{font-size:22px;margin:28px 0 10px}
.prose ul,.prose ol{padding-left:22px;margin:0 0 20px} .prose li{margin-bottom:8px}
.prose a{color:var(--orange);text-decoration:underline;text-underline-offset:2px}
.prose blockquote,.callout{border-left:4px solid var(--orange);background:var(--tint);padding:18px 22px;margin:24px 0;border-radius:0 var(--radius) var(--radius) 0}
.small-cap{font-family:var(--label);font-weight:700;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}

/* newsletter */
.news{max-width:660px;margin:0 auto;text-align:center}
.news form{display:flex;gap:12px;justify-content:center;flex-wrap:wrap;margin-top:24px}
.news input{font-family:var(--body);font-size:15px;padding:15px 18px;min-width:290px;border:1.5px solid rgba(255,255,255,.4);border-radius:999px;background:rgba(255,255,255,.1);color:var(--cream)}
.news input::placeholder{color:#AEBAC6}
.news .consent{font-size:12.5px;color:#AEBAC6;max-width:440px;margin:16px auto 0;display:flex;gap:8px;text-align:left}
.news .consent a{color:#fff;text-decoration:underline}

/* footer */
footer{background:var(--navy);color:#CBD3DB;padding:64px 0 40px}
.fgrid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:32px}
.fgrid h6{font-family:var(--label);font-weight:700;font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold);margin:0 0 14px}
.fgrid a{display:block;color:#AAB4BE;font-size:14px;margin-bottom:9px} .fgrid a:hover{color:#fff}
.fabout{color:#8E99A4;font-size:13.5px;max-width:250px;margin:14px 0 0;line-height:1.6}
.fbottom{border-top:1px solid rgba(236,230,216,.14);margin-top:40px;padding-top:20px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;font-family:var(--label);font-size:12px;letter-spacing:.05em;color:#7C8791}

@media (max-width:920px){
  .hero .grid,.feature{grid-template-columns:1fr;gap:30px}
  .feature.alt .txt{order:1}.feature.alt .art{order:2}
  .cards,.cards.four{grid-template-columns:1fr 1fr}
  .links{position:absolute;top:64px;left:0;right:0;flex-direction:column;gap:0;background:var(--page);border-bottom:1px solid var(--line);padding:8px 30px 16px;display:none}
  .links.open{display:flex}
  .links a{padding:12px 0;border-bottom:1px solid var(--line)}
  .burger{display:inline-flex}
  .fgrid{grid-template-columns:1fr 1fr}
  .hero-art{min-height:300px}
}
@media (max-width:600px){ .cards,.cards.two,.cards.four{grid-template-columns:1fr} .prices{grid-template-columns:1fr 1fr} }
@media (prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto}.ticker .track,.scroller .strip{animation:none}.scroller{overflow-x:auto}}

/* ===== Article / long-form components ===== */
.art-hero{background:var(--navy);color:var(--cream);padding:58px 0 52px;border-bottom:1px solid var(--line)}
.art-hero .crumb{font-family:var(--label);font-weight:600;text-transform:uppercase;letter-spacing:.1em;font-size:12px;color:#AEBAC6;margin-bottom:16px}
.art-hero .crumb a{color:#AEBAC6}
.meta-row{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:6px 0}
.pill{font-family:var(--label);font-weight:600;text-transform:uppercase;letter-spacing:.08em;font-size:11.5px;color:var(--cream);border:1.5px solid rgba(236,230,216,.32);padding:6px 12px;border-radius:999px}
.pill.solid{background:var(--orange);border-color:var(--orange);color:#fff}
.art-title{font-family:var(--display);text-transform:uppercase;color:var(--cream);font-size:clamp(38px,6.2vw,74px);line-height:.98;letter-spacing:.5px;margin:16px 0 16px}
.art-title em{color:var(--gold);font-style:normal}
.art-lede{font-size:19px;line-height:1.6;color:#C6CFD8;max-width:62ch;margin:0}
.byline{font-family:var(--label);font-weight:500;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:#8E99A4;margin-top:20px;line-height:1.6}
.art-grid{max-width:1180px;margin:0 auto;padding:60px 30px;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:48px;align-items:start}
.art-grid .prose{max-width:none;margin:0}
.small-cap{font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:12px;color:var(--orange)}
.callout{border-left:4px solid var(--orange);background:var(--tint);padding:20px 24px;margin:26px 0;font-size:18px;line-height:1.55;color:var(--ink);border-radius:0 var(--radius) var(--radius) 0}
.callout cite{display:block;font-style:normal;font-family:var(--label);text-transform:uppercase;letter-spacing:.05em;font-size:11px;color:var(--muted);margin-top:12px}
.note-box{background:var(--navy);color:#C6CFD8;border-radius:var(--radius);padding:22px 24px;margin:24px 0;border-left:4px solid var(--gold)}
.note-box .bl{display:block;font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.05em;font-size:12px;color:var(--gold);margin-bottom:8px}
.note-box p{margin:0;font-size:15.5px;line-height:1.65}
.note-box strong{color:var(--cream)}
.note-box a{color:var(--gold);text-decoration:underline}
.note-box.teal{border-left-color:var(--teal)}.note-box.teal .bl{color:var(--teal)}
.note-box.purple{border-left-color:#c3b7e6}.note-box.purple .bl{color:#c3b7e6}
