.dont-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}
.dont-card{background:var(--navy);color:#C6CFD8;border-radius:var(--radius);padding:20px 22px}
.dont-card b{display:block;font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.03em;font-size:12.5px;color:var(--gold);margin-bottom:8px;line-height:1.35}
.dont-card p{margin:0;font-size:14.5px;line-height:1.6}
.dont-card strong{color:var(--cream)}
.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}
.compare-card{background:var(--card);border:1px solid var(--line);border-top:4px solid var(--teal);border-radius:var(--radius);padding:20px 22px}
.compare-card.good{border-top-color:var(--teal)}.compare-card.bad{border-top-color:var(--orange)}
.compare-card b{display:block;font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.03em;font-size:12.5px;color:var(--ink);margin-bottom:8px}
.compare-card p{margin:0;font-size:14.5px;color:var(--muted);line-height:1.6}
.checklist{display:grid;gap:12px;margin:16px 0}
.checklist .item{background:var(--card);border:1px solid var(--line);border-left:3px solid var(--teal);border-radius:0 var(--radius) var(--radius) 0;padding:14px 18px}
.checklist .item p{margin:0;font-size:16px}
.checklist .item strong{color:var(--ink)}
.steps{display:grid;gap:12px;margin:18px 0}
.step{display:grid;grid-template-columns:52px 1fr;gap:16px;align-items:start;background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:16px 18px}
.step-n{font-family:var(--display);font-size:26px;color:var(--orange);line-height:1}
