.step-d{font-size:14.5px;color:var(--muted);line-height:1.55}
.full-src{background:var(--tint);border:1px solid var(--line);border-radius:var(--radius);padding:24px 26px;margin:30px 0}
.full-src h4{font-family:var(--label);text-transform:uppercase;letter-spacing:.08em;font-size:13px;color:var(--orange);margin:0 0 12px}
.full-src ol{margin:0;padding-left:18px}.full-src li{font-size:12.5px;color:var(--muted);line-height:1.5;margin-bottom:8px}
aside .side-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:22px;margin-bottom:16px}
.side-card h5{font-family:var(--label);text-transform:uppercase;letter-spacing:.05em;font-size:12px;color:var(--orange);margin:0 0 8px}
.side-card p{font-size:14px;color:var(--muted);line-height:1.6;margin:0 0 10px}
.side-card .link{font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.04em;font-size:12.5px;color:var(--teal)}
.side-card.accent{background:var(--gold);border-color:var(--gold)}
.side-card.accent h5{color:#2A1E06}.side-card.accent p{color:#4a3712}.side-card.accent .link{color:#161f29}
.side-card.dark{background:var(--navy);border-color:var(--navy)}
.side-card.dark h5{color:var(--gold)}.side-card.dark p{color:#C6CFD8}.side-card.dark strong{color:var(--cream)}.side-card.dark .link{color:var(--teal)}
.share-bar{display:flex;align-items:center;gap:10px;margin:22px 0 0;flex-wrap:wrap}
.share-label{font-family:var(--label);text-transform:uppercase;letter-spacing:.1em;font-size:11px;color:#8E99A4}
.share-ico{display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border:1.5px solid rgba(236,230,216,.3);color:var(--cream);border-radius:10px}
