@media (max-width:920px){.art-grid{grid-template-columns:1fr;padding:44px 20px}.dont-grid,.compare-grid,.stat-row,.stat-row.two{grid-template-columns:1fr}}

/* fix: keep body text light inside dark accent cards (beats .prose p) */
.note-box p,.dont-card p{color:#C6CFD8}
.note-box strong,.dont-card strong{color:var(--cream)}

/* more article components (guides, dispatches) */
.stop-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:20px 0}
.stop-card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:20px 22px}
