/* shared CTA block (used mid-article) */
.cp-cta{max-width:760px;margin:52px auto;background:var(--navy);border-radius:var(--radius-lg);padding:38px 34px;color:#C6CFD8}
.cp-cta .eyebrow{color:var(--gold)}
