/* nav coaching CTA - keep both buttons on desktop/tablet, drop the secondary on phones */
@media (max-width:600px){.nav-explore{display:none}}

/* photo-backed art panels: a real image under a brand-colour duotone wash */
.art.photo{background-size:cover;background-position:center}
.art.photo .ico{display:none}
.art.photo::before{content:"";position:absolute;inset:0;z-index:1;mix-blend-mode:multiply;opacity:.44}
/* solid fallback colour so a not-yet-loaded photo never shows through */
.art.gold.photo{background-color:var(--orange)}.art.orange.photo{background-color:#a54a12}
.art.navy.photo{background-color:var(--navy)}.art.red.photo{background-color:var(--red)}.art.teal.photo{background-color:#2f7f97}
.art.gold.photo::before{background:linear-gradient(150deg,var(--gold),var(--orange))}
.art.orange.photo::before{background:linear-gradient(150deg,var(--orange),#a54a12)}
.art.navy.photo::before{background:linear-gradient(150deg,#22303f,var(--navy))}
.art.red.photo::before{background:linear-gradient(150deg,#d85a4c,var(--red))}
.art.teal.photo::before{background:linear-gradient(150deg,var(--teal),#2f7f97)}
.art.photo .cap,.art.photo .ico-lead,.art.photo .sticker{z-index:3}
/* small surfaces need a heavier wash so labels stay legible */
.cover.photo::before,.card .top.photo::before{opacity:.58}
.art.navy.photo::before{opacity:.40}
.card .top.photo .ico{display:none}
/* dark article header bands with an image behind the display type */
.art-hero.photo{position:relative;background-size:cover;background-position:center}
.art-hero.photo::before{content:"";position:absolute;inset:0;z-index:0;background:linear-gradient(150deg,rgba(20,26,34,.86),rgba(20,26,34,.93))}
.art-hero.photo .wrap{position:relative;z-index:1}

/* poster treatment: punk collages shown full-colour with only a legibility scrim */
.art.poster{background-size:cover;background-position:center;background-color:var(--navy)}
.art.poster::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(160deg,rgba(18,24,32,.34),rgba(18,24,32,0) 45%,rgba(18,24,32,.36))}
.art.poster .ico{display:none}
.art.poster .cap,.art.poster .ico-lead,.art.poster .sticker,.art.poster h4,.art.poster .cover-tag{z-index:3}
.cover.poster::before{background:linear-gradient(180deg,rgba(18,24,32,.25),rgba(18,24,32,.7))}
.card .top.poster::before{background:linear-gradient(180deg,rgba(18,24,32,.15),rgba(18,24,32,.45))}

/* Loudspeaker edition story cards (.case) - light, matches dispatch components */
.case{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--orange);border-radius:var(--radius);padding:22px 24px;margin:24px 0;box-shadow:0 14px 34px -22px rgba(22,31,41,.4)}
.case .cl{display:block;font-family:var(--label);font-weight:700;text-transform:uppercase;letter-spacing:.06em;font-size:11.5px;color:var(--muted);margin-bottom:10px}
