.case h4 span{color:var(--orange)!important}
.case p{color:var(--ink);font-size:16px;line-height:1.66;margin:0 0 12px}
.case a{color:var(--orange)!important}
.note-box.amber{border-left-color:var(--gold)}.note-box.amber .bl{color:var(--gold)}
