/* ===== Comquat landing pages (Nov 2026). Same template as cv.the-common-people.com.
   Interview Prep = leaf green #1F6B45, CV Rewrite = kumquat #FF8A1F. Ink #17191C, peel #FFF3E2, pith #E9DCC8, muted #5B5F66.
   Type: Bricolage Grotesque (headlines, sentence case), DM Sans (everything else). ===== */
body.cq-landing{--navy:#17191C;--cream:#FFF3E2;--gold:#FF8A1F;--teal:#3E9A5F;--orange:#1F6B45;--ink:#17191C;--muted:#5B5F66;--tint:#FFF3E2;--line:#E9DCC8;
  --display:"Bricolage Grotesque","DM Sans",system-ui,sans-serif;--label:"DM Sans",system-ui,sans-serif;--body:"DM Sans",system-ui,sans-serif;font-family:var(--body);color:#17191C}
body.cq-landing h1,body.cq-landing h2,body.cq-landing h3,body.cq-landing h4{font-weight:800;text-transform:none;letter-spacing:-.015em;line-height:1.05}
