body.cq-landing .faq a{color:#1F6B45}
body.cq-landing .focus{border-left-color:#3E9A5F}
body.cq-landing .slot{background:#FF8A1F;color:#17191C}
body.cq-landing footer{background:#17191C}
body.cq-landing .nav-book{background:#FF8A1F!important;color:#17191C!important}
.cq-brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;line-height:1}
