.hero-c p[style*="border-left"]{border-left-color:var(--orange)!important}
.hero-c .cta{display:flex;gap:14px;flex-wrap:wrap;margin-top:26px;align-items:center}
.hero-c .btn.ghost{color:var(--navy)!important;border-color:var(--navy)!important}
.hero-c .btn.on-color{background:var(--navy);color:var(--cream)}
.hero-c .trust{color:#4A5661}
.hero-c .trust b{color:var(--navy)}
.hero-c .crumb,.hero-c .crumb a{color:#4A5661}
.hero-c .crumb a:hover{color:var(--orange)}
.hero-c .pill{color:var(--navy);border-color:var(--navy)}
.hero-c .pill.solid{background:var(--navy);border-color:var(--navy);color:var(--cream)}
.hero-c .byline,.hero-c .share-label{color:#56626D}
.hero-c .share-ico{color:var(--navy);border-color:rgba(22,31,41,.35)}
.hero-c .share-ico:hover{color:var(--orange);border-color:var(--orange)}
.hero-c .jump-row a{color:var(--navy);border-color:rgba(22,31,41,.35)}
.hero-c .jump-row a:hover{color:#B3541A;border-color:var(--orange)}
.hero-c [style*="font-family:'Oswald'"],.hero-c [style*="font-family:var(--label)"]{color:var(--navy)!important}
.hero-c .mark-underline::after{display:none}
.hero-c .mark-underline{background:linear-gradient(180deg,transparent 62%,var(--gold) 62%,var(--gold) 92%,transparent 92%);padding:0 4px}
.hc-frame{position:relative;margin:0 0 22px;background:#FFFFFF;padding:14px;border-radius:6px;box-shadow:0 24px 50px -24px rgba(22,31,41,.55);transform:rotate(-2deg)}
.hc-frame::before{content:"";position:absolute;top:-12px;left:50%;margin-left:-55px;width:110px;height:26px;background:rgba(224,176,60,.75);transform:rotate(-3deg)}
.hc-frame img{display:block;width:100%;height:auto;aspect-ratio:3/2;object-fit:cover;border-radius:3px}
.hc-frame figcaption{position:absolute;left:22px;bottom:-18px;font-family:var(--display);font-size:20px;letter-spacing:1px;text-transform:uppercase;color:var(--cream);background:var(--navy);padding:7px 14px 8px;border-radius:4px;transform:rotate(2deg);line-height:1.1}
@media (max-width:920px){
  .hero-c{padding:40px 0 54px}
  .hero-c .hc-grid{grid-template-columns:minmax(0,1fr);gap:40px}
  .hc-frame{transform:rotate(-1.2deg);padding:10px}
  .hc-frame figcaption{font-size:15px;left:14px}
}
@media (max-width:600px){
  .feature .art,.cf-home-art{min-height:0}
  .nav .plates.brand img{height:38px}
  .nav-actions .nav-book{padding:10px 14px;font-size:13px;white-space:nowrap}
}
.consent span{min-width:0;flex:1}
html,body{overflow-x:clip}
/* Buttons, Nov 2026: same type as the menu, brand teal, slimmer tactile buttons.
   Comquat landing pages keep their own button style. */
body:not(.cq-landing) .btn{font-family:var(--label);font-weight:600;font-size:14px;letter-spacing:.05em;line-height:1.2;text-transform:uppercase;padding:10px 18px;border:2px solid transparent;border-radius:6px;background:var(--teal);color:var(--navy);box-shadow:0 3px 0 #2F7F97;transition:transform .1s ease,box-shadow .1s ease,background .1s ease}
body:not(.cq-landing) .btn.lg{font-size:15px;padding:12px 22px}
body:not(.cq-landing) .btn:hover{background:#6BB6CD;transform:translateY(1px);box-shadow:0 2px 0 #2F7F97}
body:not(.cq-landing) .btn:active{transform:translateY(3px);box-shadow:0 0 0 #2F7F97}
body:not(.cq-landing) .btn:focus-visible{outline:2px solid var(--navy);outline-offset:3px}
/* outline buttons keep their outline, same shape */
body:not(.cq-landing) .btn.ghost{background:transparent;color:var(--navy);border-color:var(--navy);box-shadow:0 3px 0 rgba(22,31,41,.25)}
body:not(.cq-landing) .btn.ghost:hover{background:rgba(90,169,194,.14);box-shadow:0 2px 0 rgba(22,31,41,.25)}
body:not(.cq-landing) .band-navy .btn.ghost,body:not(.cq-landing) .art .btn.ghost{color:var(--cream);border-color:rgba(236,230,216,.6);box-shadow:0 3px 0 rgba(0,0,0,.35)}
/* cream buttons sitting on coloured panels */
body:not(.cq-landing) .btn.on-color{background:var(--cream);color:var(--navy);box-shadow:0 3px 0 rgba(0,0,0,.28)}
body:not(.cq-landing) .btn.on-color:hover{background:#F6F2E9;box-shadow:0 2px 0 rgba(0,0,0,.28)}
/* on a teal panel a teal button would vanish, so go navy */
body:not(.cq-landing) .band-teal .btn:not(.ghost):not(.on-color){background:var(--navy);color:var(--cream);box-shadow:0 3px 0 #0B1118}
/* header button */
.nav-actions .nav-book{padding:8px 16px;white-space:nowrap}
@media (min-width:921px) and (max-width:1260px){.nav-actions .nav-book{font-size:13.5px;letter-spacing:.04em}}
@media (min-width:921px) and (max-width:1120px){.nav-actions .nav-book{font-size:13px;letter-spacing:.03em}}
@media (max-width:600px){body:not(.cq-landing) .nav-actions .nav-book{font-size:13px;padding:7px 12px}}

/* Comquat-branded app promos (Dispatches) */
.cp-cta.cq-cta{background:#17191C;color:#D9D4CB}
.cq-cta .cq-cta-brand{display:inline-block;margin-bottom:16px}
.cq-cta .cq-cta-brand img{display:block;height:32px;width:auto}
.cq-cta .eyebrow{display:block;color:#FF8A1F}
.cq-cta h3{color:#FFF3E2}
body:not(.cq-landing) .btn.cq-btn{background:#1F6B45;color:#FFF3E2;box-shadow:0 3px 0 #123F28}
body:not(.cq-landing) .btn.cq-btn:hover{background:#26804F;box-shadow:0 2px 0 #123F28}
body:not(.cq-landing) .btn.cq-btn:active{box-shadow:0 0 0 #123F28}
body:not(.cq-landing) .btn.cq-btn-alt{background:#FF8A1F;color:#17191C;box-shadow:0 3px 0 #B85A08}
body:not(.cq-landing) .btn.cq-btn-alt:hover{background:#FFA54A;box-shadow:0 2px 0 #B85A08}
body:not(.cq-landing) .btn.cq-btn-alt:active{box-shadow:0 0 0 #B85A08}
.cq-nav{white-space:nowrap}
@media (max-width:600px){.cq-ad-wrap{padding:28px 14px!important}.cq-ad-wrap>div{padding:30px 20px!important}.cq-ad-wrap h2{font-size:26px!important}}
/* Nav spacing: room for the Comquat icons beside Interview Prep and CV Rewrite */
@media (min-width:921px) and (max-width:1400px){.nav .row>.links{gap:8px 16px}}
@media (min-width:921px) and (max-width:1120px){.nav .row>.links{gap:8px 11px}}

/* ===== Header fit (17 Nov 2026): coaching button sits beside the logo, the menu gets the whole row
   beneath it and wraps if it must, so nothing overlaps at laptop widths ===== */
@media (min-width:921px){
  .nav .row{grid-template-columns:minmax(0,1fr) auto!important;grid-template-areas:"brand actions" "links links"!important}
  .nav .row>.links{flex-wrap:wrap!important;white-space:normal!important;justify-self:start;row-gap:10px}
  .nav .row>.links a{white-space:nowrap}
}
/* Comquat landing pages on phones: logo and coaching button fit the screen */
@media (max-width:600px){
  body.cq-landing .nav .cq-brand .cq-feat{display:none!important}
  body.cq-landing .nav .cq-brand{margin-right:8px}
  body.cq-landing .nav .cq-brand img{height:28px;width:auto}
  body.cq-landing .nav-actions{gap:8px}
  body.cq-landing .nav-actions .nav-book{font-size:12px!important;padding:7px 11px!important;letter-spacing:.02em}
}
/* Long buttons (like an email address) wrap on phones instead of running off the screen */
@media (max-width:600px){.btn{white-space:normal;overflow-wrap:anywhere;max-width:100%;text-align:center}}
/* Two-column blocks with a fixed photo column stack on phones */
@media (max-width:700px){[style*="grid-template-columns:300px 1fr"]{grid-template-columns:1fr!important;gap:22px!important}}
